/* DAWAH X — ahmad, অধ্যায় 129 · খণ্ড 129 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][129]=[[25601,25601,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏وَعَلِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ جَافَى بَيْنَ يَدَيْهِ حَتَّى يَرَى مَنْ خَلْفَهُ ‏ ‏وَضَحَ ‏ ‏إِبْطَيْهِ ‏","","",""],[25602,25602,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاتَتْهُ رَكْعَتَانِ قَبْلَ الْعَصْرِ فَصَلَّاهُمَا بَعْدُ ‏","","",""],[25603,25603,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏كَثِيرَ بْنَ فَرْقَدٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكِ بْنِ حُذَافَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أُمِّهِ الْعَالِيَةِ بِنْتِ سُمَيْعٍ ‏ ‏أَوْ ‏ ‏سُبَيْعٍ ‏ ‏الشَّكُّ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرِجَالٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يَجُرُّونَ شَاةً لَهُمْ مِثْلَ الْحِمَارِ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَخَذْتُمْ ‏ ‏إِهَابَهَا ‏ ‏قَالُوا إِنَّهَا مَيْتَةٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطَهِّرُهَا الْمَاءُ ‏ ‏وَالْقَرَظُ ‏","","",""],[25604,25604,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْبُوذٌ ‏ ‏أَنَّ ‏ ‏أُمَّهُ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهَا بَيْنَا هِيَ جَالِسَةٌ عِنْدَ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ دَخَلَ عَلَيْهَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَتْ مَا لَكَ ‏ ‏شَعِثًا ‏ ‏قَالَ ‏ ‏أُمُّ عَمَّارٍ ‏ ‏مُرَجِّلَتِي ‏ ‏حَائِضٌ فَقَالَتْ أَيْ بُنَيَّ وَأَيْنَ الْحَيْضَةُ مِنْ الْيَدِ لَقَدْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَى إِحْدَانَا وَهِيَ مُتَّكِئَةٌ حَائِضٌ قَدْ عَلِمَ أَنَّهَا حَائِضٌ ‏ ‏فَيَتَّكِئُ ‏ ‏عَلَيْهَا ‏ ‏فَيَتْلُو الْقُرْآنَ وَهُوَ ‏ ‏مُتَّكِئٌ ‏ ‏عَلَيْهَا ‏ ‏أَوْ يَدْخُلُ عَلَيْهَا قَاعِدَةً وَهِيَ حَائِضٌ ‏ ‏فَيَتَّكِئُ ‏ ‏فِي حِجْرِهَا ‏ ‏فَيَتْلُو الْقُرْآنَ فِي حِجْرِهَا ‏ ‏وَتَقُومُ وَهِيَ حَائِضٌ فَتَبْسُطُ لَهُ ‏ ‏الْخُمْرَةَ ‏ ‏فِي مُصَلَّاهُ ‏ ‏وقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏خُمْرَتَهُ ‏ ‏فَيُصَلِّي عَلَيْهَا فِي بَيْتِي أَيْ بُنَيَّ وَأَيْنَ الْحَيْضَةُ مِنْ الْيَدِ ‏","","",""],[25605,25605,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ مَعْبَدٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَ أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏مَسْجِدَ الْكَعْبَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25606,25606,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةٌ فِيهِ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏مَسْجِدَ الْكَعْبَةِ ‏","","",""],[25607,25607,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ فَرُّوخٍ أَبُو بَكَّارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏خَرَجَ عَلَى جَنَازَةٍ فَلَمَّا اسْتَوَى ظَنُّوا أَنَّهُ يُكَبِّرُ فَالْتَفَتَ فَقَالَ اسْتَوُوا لِتَحْسُنَ شَفَاعَتُكُمْ فَإِنِّي لَوْ اخْتَرْتُ رَجُلًا لَاخْتَرْتُ هَذَا إِلَّا أَنَّهُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَلِيطٍ ‏ ‏عَنْ ‏ ‏إِحْدَى ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ وَهِيَ ‏ ‏مَيْمُونَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ ‏ ‏يُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ النَّاسِ إِلَّا ‏ ‏شُفِّعُوا ‏ ‏فِيهِ ‏ ‏قَالَ ‏ ‏فَسَأَلْتُ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏عَنْ الْأُمَّةِ ‏ ‏فَقَالَ ‏ ‏أَرْبَعُونَ ‏","","",""],[25608,25608,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏صَلَاةَ الْعَصْرِ فَأَرْسَلَ إِلَى ‏ ‏مَيْمُونَةَ ‏ ‏ثُمَّ أَتْبَعَهُ رَجُلًا آخَرَ فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُجَهِّزُ ‏ ‏بَعْثًا ‏ ‏وَلَمْ يَكُنْ عِنْدَهُ ‏ ‏ظَهْرٌ ‏ ‏فَجَاءَهُ ‏ ‏ظَهْرٌ ‏ ‏مِنْ الصَّدَقَةِ فَجَعَلَ يَقْسِمُهُ بَيْنَهُمْ فَحَبَسُوهُ حَتَّى أَرْهَقَ الْعَصْرَ وَكَانَ ‏ ‏يُصَلِّي قَبْلَ الْعَصْرِ رَكْعَتَيْنِ أَوْ مَا شَاءَ اللَّهُ فَصَلَّى ‏ ‏الْعَصْرَ ثُمَّ رَجَعَ فَصَلَّى مَا كَانَ ‏ ‏يُصَلِّي قَبْلَهَا وَكَانَ إِذَا صَلَّى صَلَاةً أَوْ فَعَلَ شَيْئًا يُحِبُّ أَنْ يُدَاوِمَ عَلَيْهِ ‏","","",""],[25609,25609,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتَدَانَ دَيْنًا يَعْلَمُ اللَّهُ عَزَّ وَجَلَّ مِنْهُ أَنَّهُ يُرِيدُ أَدَاءَهُ أَدَّاهُ اللَّهُ عَنْهُ ‏","","",""],[25610,25610,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ الْأَصَمِّ ‏ ‏ابْنَ أَخِي ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَهَا وَهُمَا حَلَالَانِ ‏ ‏بِسَرِفٍ ‏ ‏بَعْدَمَا رَجَعَ ‏","","",""],[25611,25611,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِسْلًا فَاغْتَسَلَ مِنْ الْجَنَابَةِ ثُمَّ أَتَيْتُهُ بِثَوْبٍ حِينَ اغْتَسَلَ فَقَالَ بِيَدِهِ هَكَذَا ‏ ‏يَعْنِي رَدَّهُ ‏","","",""],[25612,25612,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِسْلًا فَاغْتَسَلَ مِنْ الْجَنَابَةِ وَأَكْفَأَ الْإِنَاءَ بِشِمَالِهِ عَلَى يَمِينِهِ فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فِي الْإِنَاءِ ‏ ‏فَأَفَاضَ ‏ ‏عَلَى فَرْجِهِ ثُمَّ دَلَكَ يَدَهُ بِالْحَائِطِ ‏ ‏أَوْ الْأَرْضِ ‏ ‏ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ ‏ ‏أَفَاضَ ‏ ‏عَلَى رَأْسِهِ ثَلَاثًا ثُمَّ ‏ ‏أَفَاضَ ‏ ‏عَلَى سَائِرِ جَسَدِهِ الْمَاءَ ثُمَّ ‏ ‏تَنَحَّى ‏ ‏فَغَسَلَ رِجْلَيْهِ ‏","","",""],[25613,25613,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ ‏ ‏جَافَى ‏ ‏حَتَّى يَرَى مَنْ خَلْفَهُ بَيَاضَ إِبْطَيْهِ ‏","","",""],[25614,25614,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏قَالَ ‏ ‏أَظُنُّ ‏ ‏أَبَا خَالِدٍ الْوَالِبِيَّ ‏ ‏ذَكَرَهُ عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[25615,25615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُهَا وَهِيَ حَائِضٌ فَوْقَ ‏ ‏الْإِزَارِ ‏","","",""],[25616,25616,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ فَأْرَةٍ وَقَعَتْ فِي سَمْنٍ قَالَ خُذُوهَا وَمَا حَوْلَهَا فَأَلْقُوهُ ‏","","",""],[25617,25617,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏قَالَ سَأَلْتُ ‏ ‏مِقْسَمًا ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏أُوتِرُ ‏ ‏بِثَلَاثٍ ثُمَّ أَخْرُجُ إِلَى الصَّلَاةِ مَخَافَةَ أَنْ تَفُوتَنِي قَالَ لَا يَصْلُحُ إِلَّا بِخَمْسٍ أَوْ سَبْعٍ فَأَخْبَرْتُ ‏ ‏مُجَاهِدًا ‏ ‏وَيَحْيَى بْنَ الجَزَّارِ ‏ ‏بِقَوْلِهِ فَقَالَا لِي سَلْهُ عَمَّنْ فَسَأَلْتُهُ فَقَالَ عَنْ الثِّقَةِ عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏وَعَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25618,25618,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[25619,25619,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏مَوْلَى ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُدَيَّةَ ‏ ‏مَوْلَاةِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏الْمَرْأَةَ مِنْ نِسَائِهِ وَهِيَ حَائِضٌ إِذَا كَانَ عَلَيْهَا إِزَارٌ يَبْلُغُ أَنْصَافَ الْفَخِذَيْنِ أَوْ الرُّكْبَتَيْنِ مُحْتَجِزَةً بِهِ ‏","","",""],[25620,25620,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[25621,25621,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَخْبَرَتْنِي ‏ ‏مَيْمُونَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ شَاةً مَاتَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا ‏ ‏دَبَغْتُمْ ‏ ‏إِهَابَهَا ‏ ‏فَاسْتَمْتَعْتُمْ بِهِ ‏","","",""],[25622,25622,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏بُدَيَّةَ ‏ ‏مَوْلَاةِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏الْمَرْأَةَ مِنْ نِسَائِهِ حَائِضًا تَكُونُ عَلَيْهَا الْخِرْقَةُ إِلَى الرُّكْبَتَيْنِ أَوْ إِلَى أَنْصَافِ الْفَخِذَيْنِ ‏","","",""],[25623,25623,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ نِسَاءَهُ فَوْقَ ‏ ‏الْإِزَارِ ‏ ‏وَهُنَّ حُيَّضٌ ‏","","",""],[25624,25624,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادِ بْنِ الْهَادِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ ‏ ‏يُبَاشِرَ ‏ ‏امْرَأَةً مِنْ نِسَائِهِ وَهِيَ حَائِضٌ أَمَرَهَا ‏ ‏فَاتَّزَرَتْ ‏","","",""],[25625,25625,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِسْلًا وَسَتَرْتُهُ ‏ ‏فَصَبَّ عَلَى يَدِهِ فَغَسَلَهَا مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَلَا أَدْرِي أَذَكَرَ الثَّالِثَةَ أَمْ لَا ‏ ‏قَالَ ثُمَّ أَفْرَغَ بِيَمِينِهِ عَلَى شِمَالِهِ فَغَسَلَ فَرْجَهُ ثُمَّ دَلَكَ يَدَهُ بِالْأَرْضِ ‏ ‏أَوْ بِالْحَائِطِ ‏ ‏ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ قَالَ وَغَسَلَ رَأْسَهُ ثُمَّ صَبَّ عَلَى جَسَدِهِ ثُمَّ ‏ ‏تَنَحَّى ‏ ‏فَغَسَلَ قَدَمَيْهِ قَالَتْ فَنَاوَلْتُهُ خِرْقَةً قَالَ فَقَالَ هَكَذَا وَأَشَارَ بِيَدِهِ أَنْ لَا أُرِيدُهَا ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ ‏ ‏هُوَ كَذَلِكَ وَلَمْ يُنْكِرْهُ ‏ ‏و قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَا بَأْسَ بِالْمِنْدِيلِ إِنَّمَا هِيَ عَادَةٌ ‏","","",""],[25626,25626,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ جُبَيْرٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَذَكَرَ حَدِيثًا ‏ ‏قَالَ ‏ ‏وَسَأَلَهُ رَجُلٌ عَمَّا يُقْتَلُ مِنْ ‏ ‏الدَّوَابِّ ‏ ‏فَقَالَ أَخْبَرَتْنِي ‏ ‏إِحْدَى نِسْوَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏أَمَرَ بِقَتْلِ الْفَأْرَةِ وَالْعَقْرَبِ وَالْكَلْبِ ‏ ‏الْعَقُورِ ‏ ‏وَالْحُدَيَّا وَالْغُرَابِ ‏","","",""],[25627,25627,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنِ ‏ ‏ابْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْتَهِي النَّاسُ عَنْ غَزْوِ هَذَا ‏ ‏الْبَيْتِ ‏ ‏حَتَّى يَغْزُوَهُ جَيْشٌ حَتَّى إِذَا كَانُوا ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ خُسِفَ بِأَوَّلِهِمْ وَآخِرِهِمْ وَلَمْ يَنْجُ أَوْسَطُهُمْ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ الْمُكْرَهَ مِنْهُمْ قَالَ يَبْعَثُهُمْ اللَّهُ عَلَى مَا فِي أَنْفُسِهِمْ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَحَدَّثَنِي ‏ ‏عُبَيْدُ بْنُ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏نَحْوَ هَذَا الْحَدِيثِ ‏","","",""],[25628,25628,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ يَعْنِي ابْنَ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنِ ‏ ‏ابْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْتَهِي النَّاسُ عَنْ غَزْوِ هَذَا ‏ ‏الْبَيْتِ ‏ ‏حَتَّى إِذَا كَانُوا ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ خُسِفَ أَوَّلُهُمْ وَآخِرُهُمْ وَلَمْ يَنْجُ أَوْسَطُهُمْ قَالُوا يَا رَسُولَ اللَّهِ يَكُونُ فِيهِمْ الْمُكْرَهُ قَالَ يَبْعَثُهُمْ اللَّهُ عَلَى مَا فِي أَنْفُسِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْمُرْهِبِيُّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْتَهِي النَّاسُ وَذَكَرَ الْحَدِيثَ وَسَاقَهُ ‏","","",""],[25629,25629,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَعْلَى بْنَ حَكِيمٍ ‏ ‏عَنْ ‏ ‏صُهَيْرَةَ بِنْتِ جَيْفَرٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ ‏ ‏عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَسَأَلْتُ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَتْ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏","","",""],[25630,25630,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعْتَكِفًا ‏ ‏فَأَتَيْتُهُ أَزُورُهُ لَيْلًا فَحَدَّثْتُهُ ثُمَّ قُمْتُ ‏ ‏فَانْقَلَبْتُ ‏ ‏فَقَامَ مَعِي ‏ ‏يَقْلِبُنِي ‏ ‏وَكَانَ مَسْكَنُهَا فِي دَارِ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏فَمَرَّ رَجُلَانِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَلَمَّا رَأَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْرَعَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏رِسْلِكُمَا ‏ ‏إِنَّهَا ‏ ‏صَفِيَّةُ بِنْتُ حُيَيٍّ ‏ ‏فَقَالَا سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَجْرِي مِنْ الْإِنْسَانِ مَجْرَى الدَّمِ وَإِنِّي خَشِيتُ أَنْ ‏ ‏يَقْذِفَ ‏ ‏فِي قُلُوبِكُمَا شَرًّا ‏ ‏أَوْ قَالَ شَيْئًا ‏","","",""],[25631,25631,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَعْلَى بْنَ حَكَمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏صُهَيْرَةَ بِنْتِ جَيْفَرٍ ‏ ‏قَالَتْ ‏ ‏حَجَجْنَا ثُمَّ أَتَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَدَخَلْنَا عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَوَافَقْنَا عِنْدَهَا نِسْوَةً فَقَالَتْ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏","","",""],[25632,25632,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَعْلَى بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏صُهَيْرَةَ بِنْتِ جَيْفَرٍ ‏ ‏سَمِعَهُ مِنْهَا ‏ ‏قَالَتْ ‏ ‏حَجَجْنَا ثُمَّ انْصَرَفْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَدَخَلْنَا عَلَى ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏فَوَافَقْنَا عِنْدَهَا نِسْوَةً مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏فَقُلْنَ لَهَا إِنْ شِئْتُنَّ سَأَلْتُنَّ وَسَمِعْنَا وَإِنْ شِئْتُنَّ سَأَلْنَا وَسَمِعْتُنَّ فَقُلْنَا سَلْنَ فَسَأَلْنَ عَنْ أَشْيَاءَ مِنْ أَمْرِ الْمَرْأَةِ وَزَوْجِهَا وَمِنْ أَمْرِ ‏ ‏الْمَحِيضِ ‏ ‏ثُمَّ سَأَلْنَ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَتْ أَكْثَرْتُمْ عَلَيْنَا يَا أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏فِي ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَمَا عَلَى إِحْدَاكُنَّ أَنْ تَطْبُخَ تَمْرَهَا ثُمَّ تَدْلُكَهُ ثُمَّ تُصَفِّيَهُ فَتَجْعَلَهُ فِي سِقَائِهَا ‏ ‏وَتُوكِئَ عَلَيْهِ فَإِذَا طَابَ شَرِبَتْ وَسَقَتْ زَوْجَهَا ‏","","",""],[25633,25633,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏شُمَيْسَةُ ‏ ‏أَوْ ‏ ‏سُمَيَّةُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏هُوَ فِي كِتَابِي ‏ ‏سُمَيَّةُ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّ بِنِسَائِهِ فَلَمَّا كَانَ فِي بَعْضِ الطَّرِيقِ نَزَلَ رَجُلٌ فَسَاقَ بِهِنَّ فَأَسْرَعَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَاكَ سَوْقُكَ ‏ ‏بِالْقَوَارِيرِ ‏ ‏يَعْنِي النِّسَاءَ ‏ ‏فَبَيْنَا هُمْ يَسِيرُونَ بَرَكَ ‏ ‏بِصَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏جَمَلُهَا وَكَانَتْ مِنْ أَحْسَنِهِنَّ ظَهْرًا فَبَكَتْ وَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أُخْبِرَ بِذَلِكَ فَجَعَلَ يَمْسَحُ دُمُوعَهَا ‏ ‏بِيَدِهِ وَجَعَلَتْ تَزْدَادُ بُكَاءً وَهُوَ ‏ ‏يَنْهَاهَا فَلَمَّا أَكْثَرَتْ زَبَرَهَا وَانْتَهَرَهَا ‏ ‏وَأَمَرَ النَّاسَ بِالنُّزُولِ فَنَزَلُوا وَلَمْ يَكُنْ يُرِيدُ أَنْ يَنْزِلَ قَالَتْ فَنَزَلُوا وَكَانَ يَوْمِي فَلَمَّا نَزَلُوا ضُرِبَ ‏ ‏خِبَاءُ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدَخَلَ فِيهِ قَالَتْ فَلَمْ أَدْرِ عَلَامَ أُهْجَمُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَشِيتُ أَنْ يَكُونَ فِي نَفْسِهِ شَيْءٌ مِنِّي فَانْطَلَقْتُ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ لَهَا تَعْلَمِينَ أَنِّي لَمْ أَكُنْ أَبِيعُ يَوْمِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ أَبَدًا وَإِنِّي قَدْ وَهَبْتُ يَوْمِي لَكِ عَلَى أَنْ تُرْضِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنِّي قَالَتْ نَعَمْ قَالَ فَأَخَذَتْ ‏ ‏عَائِشَةُ ‏ ‏خِمَارًا ‏ ‏لَهَا قَدْ ‏ ‏ثَرَدَتْهُ ‏ ‏بِزَعْفَرَانٍ ‏ ‏فَرَشَّتْهُ بِالْمَاءِ لِيُذَكِّيَ رِيحَهُ ثُمَّ لَبِسَتْ ثِيَابَهَا ثُمَّ انْطَلَقَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَتْ طَرَفَ ‏ ‏الْخِبَاءِ ‏ ‏فَقَالَ لَهَا مَا لَكِ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ هَذَا لَيْسَ بِيَوْمِكِ قَالَتْ ذَلِكَ فَضْلُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ فَقَالَ مَعَ أَهْلِهِ فَلَمَّا كَانَ عِنْدَ ‏ ‏الرَّوَاحِ ‏ ‏قَالَ ‏ ‏لِزَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏يَا ‏ ‏زَيْنَبُ ‏ ‏أَفْقِرِي ‏ ‏أُخْتَكِ ‏ ‏صَفِيَّةَ ‏ ‏جَمَلًا وَكَانَتْ مِنْ أَكْثَرِهِنَّ ‏ ‏ظَهْرًا ‏ ‏فَقَالَتْ أَنَا أُفْقِرُ يَهُودِيَّتَكَ فَغَضِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ سَمِعَ ذَلِكَ مِنْهَا فَهَجَرَهَا فَلَمْ يُكَلِّمْهَا حَتَّى قَدِمَ ‏ ‏مَكَّةَ ‏ ‏وَأَيَّامَ ‏ ‏مِنًى ‏ ‏فِي سَفَرِهِ حَتَّى رَجَعَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالْمُحَرَّمَ وَصَفَرَ فَلَمْ يَأْتِهَا وَلَمْ يَقْسِمْ لَهَا وَيَئِسَتْ مِنْهُ فَلَمَّا كَانَ شَهْرُ رَبِيعٍ الْأَوَّلِ دَخَلَ عَلَيْهَا فَرَأَتْ ظِلَّهُ فَقَالَتْ إِنَّ هَذَا لَظِلُّ رَجُلٍ وَمَا يَدْخُلُ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنْ هَذَا فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَأَتْهُ قَالَتْ يَا رَسُولَ اللَّهِ مَا أَدْرِي مَا أَصْنَعُ حِينَ دَخَلْتَ عَلَيَّ قَالَتْ وَكَانَتْ لَهَا جَارِيَةٌ وَكَانَتْ تَخْبَؤُهَا مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ فُلَانَةُ لَكَ فَمَشَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى سَرِيرِ ‏ ‏زَيْنَبَ ‏ ‏وَكَانَ قَدْ رُفِعَ فَوَضَعَهُ بِيَدِهِ ثُمَّ ‏ ‏أَصَابَ ‏ ‏أَهْلَهُ وَرَضِيَ عَنْهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏سُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ ‏ ‏فَاعْتَلَّ ‏ ‏بَعِيرٌ ‏ ‏لِصَفِيَّةَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[25634,25634,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْمَغْرِبِ ‏ ‏بِالْمُرْسَلَاتِ عُرْفًا ‏","","",""],[25635,25635,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏أُتِيَ بِرُمَّانٍ فَأَكَلَهُ وَقَالَ حَدَّثَتْنِي ‏ ‏أُمُّ الْفَضْلِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏أَتَتْهُ بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[25636,25636,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏أُمَّ حَبِيبَةَ بِنْتَ عَبَّاسٍ ‏ ‏وَهِيَ فَوْقَ الْفَطِيمِ قَالَتْ فَقَالَ ‏ ‏لَئِنْ بَلَغَتْ بُنَيَّةُ ‏ ‏الْعَبَّاسِ ‏ ‏هَذِهِ وَأَنَا حَيٌّ لَأَتَزَوَّجَنَّهَا ‏","","",""],[25637,25637,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ ‏ ‏مُتَوَشِّحًا ‏ ‏فِي ‏ ‏ثَوْبِ ‏ ‏الْمَغْرِبِ ‏ ‏فَقَرَأَ ‏ ‏الْمُرْسَلَاتِ ‏ ‏مَا صَلَّى صَلَاةً بَعْدَهَا حَتَّى ‏ ‏قُبِضَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25638,25638,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَيْرًا ‏ ‏مَوْلَى ‏ ‏أُمِّ الْفَضْلِ أُمِّ بَنِي الْعَبَّاسِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏شَكُّوا فِي صَوْمِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏أَنَا أَعْلَمُ لَكُمْ ذَلِكَ فَبَعَثَتْ بِلَبَنٍ فَشَرِبَ ‏","","",""],[25639,25639,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ الْهَاشِمِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي فَجَاءَ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ كَانَتْ لِي امْرَأَةٌ فَتَزَوَّجْتُ عَلَيْهَا امْرَأَةً أُخْرَى فَزَعَمَتْ امْرَأَتِي الْأُولَى أَنَّهَا أَرْضَعَتْ امْرَأَتِي ‏ ‏الْحُدْثَى ‏ ‏إِمْلَاجَةً ‏ ‏أَوْ ‏ ‏إِمْلَاجَتَيْنِ ‏ ‏وَقَالَ مَرَّةً رَضْعَةً ‏ ‏أَوْ رَضْعَتَيْنِ ‏ ‏فَقَالَ ‏ ‏لَا تُحَرِّمُ ‏ ‏الْإِمْلَاجَةُ ‏ ‏وَلَا ‏ ‏الْإِمْلَاجَتَانِ ‏ ‏أَوْ قَالَ الرَّضْعَةُ أَوْ الرَّضْعَتَانِ ‏","","",""],[25640,25640,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏هِنْدَ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏الْعَبَّاسِ ‏ ‏وَهُوَ ‏ ‏يَشْتَكِي ‏ ‏فَتَمَنَّى الْمَوْتَ فَقَالَ يَا ‏ ‏عَبَّاسُ ‏ ‏يَا عَمَّ رَسُولِ اللَّهِ ‏ ‏لَا تَتَمَنَّ الْمَوْتَ إِنْ كُنْتَ مُحْسِنًا تَزْدَادُ إِحْسَانًا إِلَى إِحْسَانِكَ خَيْرٌ لَكَ وَإِنْ كُنْتَ مُسِيئًا فَإِنْ تُؤَخَّرْ ‏ ‏تَسْتَعْتِبْ ‏ ‏خَيْرٌ لَكَ فَلَا تَتَمَنَّ الْمَوْتَ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏وَإِنْ كُنْتَ مُسِيئًا فَإِنْ تُؤَخَّرْ ‏ ‏تَسْتَعْتِبْ ‏ ‏مِنْ إِسَاءَتِكَ خَيْرٌ لَكَ ‏","","",""],[25641,25641,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ أَبِي الْمُخَارِقِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ كَأَنَّ فِي بَيْتِي عُضْوًا مِنْ أَعْضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏فَجَزِعْتُ ‏ ‏مِنْ ذَلِكَ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ خَيْرًا تَلِدُ ‏ ‏فَاطِمَةُ ‏ ‏غُلَامًا فَتَكْفُلِينَهُ بِلَبَنِ ابْنِكِ ‏ ‏قُثَمٍ ‏ ‏قَالَتْ فَوَلَدَتْ ‏ ‏حَسَنًا ‏ ‏فَأُعْطِيتُهُ فَأَرْضَعْتُهُ حَتَّى تَحَرَّكَ ‏ ‏أَوْ فَطَمْتُهُ ‏ ‏ثُمَّ جِئْتُ بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَجْلَسْتُهُ فِي حِجْرِهِ فَبَالَ فَضَرَبْتُ بَيْنَ كَتِفَيْهِ فَقَالَ ارْفُقِي بِابْنِي رَحِمَكِ اللَّهُ ‏ ‏أَوْ أَصْلَحَكِ اللَّهُ ‏ ‏أَوْجَعْتِ ابْنِي قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ اخْلَعْ ‏ ‏إِزَارَكَ ‏ ‏وَالْبَسْ ثَوْبًا غَيْرَهُ حَتَّى أَغْسِلَهُ قَالَ ‏ ‏إِنَّمَا يُغْسَلُ بَوْلُ الْجَارِيَةِ ‏ ‏وَيُنْضَحُ ‏ ‏بَوْلُ الْغُلَامِ ‏","","",""],[25642,25642,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏وَهِيَ أُمُّ وَلَدِ ‏ ‏الْعَبَّاسِ ‏ ‏أُخْتُ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ فَجَعَلْتُ أَبْكِي فَرَفَعَ رَأْسَهُ فَقَالَ مَا يُبْكِيكِ قُلْتُ خِفْنَا عَلَيْكَ وَمَا نَدْرِي مَا نَلْقَى مِنْ النَّاسِ بَعْدَكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أَنْتُمْ الْمُسْتَضْعَفُونَ بَعْدِي ‏","","",""],[25643,25643,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءٌ الْخُرَاسَانِيُّ ‏ ‏عَنْ ‏ ‏لُبَابَةَ أُمِّ الْفَضْلِ ‏ ‏أَنَّهَا كَانَتْ تُرْضِعُ ‏ ‏الْحَسَنَ ‏ ‏أَوْ ‏ ‏الْحُسَيْنَ ‏ ‏قَالَتْ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاضْطَجَعَ ‏ ‏فِي مَكَانٍ مَرْشُوشٍ فَوَضَعَهُ عَلَى بَطْنِهِ فَبَالَ عَلَى بَطْنِهِ فَرَأَيْتُ الْبَوْلَ يَسِيلُ عَلَى بَطْنِهِ فَقُمْتُ إِلَى ‏ ‏قِرْبَةٍ ‏ ‏لِأَصُبَّهَا عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أُمَّ الْفَضْلِ ‏ ‏إِنَّ بَوْلَ الْغُلَامِ يُصَبُّ عَلَيْهِ الْمَاءُ وَبَوْلُ الْجَارِيَةِ يُغْسَلُ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏غُسْلًا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏كَانَ ‏ ‏عَطَاءٌ ‏ ‏يَرْوِيهِ عَنْ ‏ ‏أَبِي عَطَاءٍ ‏ ‏عَنْ ‏ ‏لُبَابَةَ ‏","","",""],[25644,25644,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏صَالِحٍ أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي رَأَيْتُ فِي مَنَامِي ‏ ‏أَنَّ ‏ ‏فِي بَيْتِي ‏ ‏أَوْ حُجْرَتِي ‏ ‏عُضْوًا مِنْ أَعْضَائِكَ قَالَ تَلِدُ ‏ ‏فَاطِمَةُ ‏ ‏إِنْ شَاءَ اللَّهُ غُلَامًا فَتَكْفُلِينَهُ فَوَلَدَتْ ‏ ‏فَاطِمَةُ ‏ ‏حَسَنًا ‏ ‏فَدَفَعَتْهُ إِلَيْهَا فَأَرْضَعَتْهُ بِلَبَنِ ‏ ‏قُثَمَ ‏ ‏وَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا أَزُورُهُ فَأَخَذَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَهُ عَلَى صَدْرِهِ فَبَالَ عَلَى صَدْرِهِ فَأَصَابَ الْبَوْلُ ‏ ‏إِزَارَهُ ‏ ‏فَزَخَخْتُ ‏ ‏بِيَدِي عَلَى كَتِفَيْهِ فَقَالَ أَوْجَعْتِ ابْنِي أَصْلَحَكِ اللَّهُ ‏ ‏أَوْ قَالَ رَحِمَكِ اللَّهُ ‏ ‏فَقُلْتُ أَعْطِنِي ‏ ‏إِزَارَكَ ‏ ‏أَغْسِلْهُ فَقَالَ ‏ ‏إِنَّمَا يُغْسَلُ بَوْلُ الْجَارِيَةِ وَيُصَبُّ عَلَى بَوْلِ الْغُلَامِ ‏","","",""],[25645,25645,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّ الرَّسُولَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُحَرِّمُ ‏ ‏الْإِمْلَاجَةُ ‏ ‏أَوْ ‏ ‏الْإِمْلَاجَتَانِ ‏","","",""],[25646,25646,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏إِنَّ آخِرَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الْمَغْرِبِ سُورَةَ ‏ ‏الْمُرْسَلَاتِ ‏","","",""],[25647,25647,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّ ‏ ‏أُمَّ الْفَضْلِ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهُمْ شَكُّوا فِي صَوْمِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَأَرْسَلَتْ إِلَيْهِ بِلَبَنٍ فَشَرِبَ وَهُوَ يَخْطُبُ النَّاسَ ‏ ‏بِعَرَفَةَ ‏ ‏عَلَى بَعِيرِهِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ مُخَارِقٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ مِثْلَ حَدِيثِ ‏ ‏عَفَّانَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏صَالِحٍ أَبِي الْخَلِيلِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25648,25648,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ الْفَضْلِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏أَنَّهُمْ ‏ ‏تَمَارَوْا ‏ ‏فِي صَوْمِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏فَبَعَثَتْ إِلَيْهِ ‏ ‏بِقَدَحٍ ‏ ‏فِيهِ لَبَنٌ فَشَرِبَهُ ‏","","",""],[25649,25649,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ الْمَعْنَى ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ ‏ ‏سَمِعَتْهُ وَهُوَ يُقْرَأُ ‏ ‏وَالْمُرْسَلَاتِ عُرْفًا ‏ ‏فَقَالَتْ يَا بُنَيَّ وَاللَّهِ لَقَدْ ذَكَّرْتَنِي بِقِرَاءَتِكَ هَذِهِ السُّورَةَ ‏ ‏إِنَّهَا لَآخِرُ مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا فِي الْمَغْرِبِ ‏","","",""],[25650,25650,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ وَحَدَّثَتْنِي ‏ ‏أُمُّ الْفَضْلِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏أَتَتْهُ بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[25651,25651,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُحَرِّمُ الْمَصَّةُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ فَذَكَرَهُ ‏","","",""],[25652,25652,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ بِأَعْلَى ‏ ‏مَكَّةَ ‏ ‏فَأَتَيْتُهُ فَجَاءَ ‏ ‏أَبُو ذَرٍّ ‏ ‏بِجَفْنَةٍ ‏ ‏فِيهَا مَاءٌ قَالَتْ إِنِّي لَأَرَى فِيهَا أَثَرَ الْعَجِينِ قَالَتْ فَسَتَرَهُ ‏ ‏يَعْنِي ‏ ‏أَبَا ذَرٍّ ‏ ‏فَاغْتَسَلَ ثُمَّ صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِ رَكَعَاتٍ وَذَلِكَ فِي الضُّحَى ‏","","",""],[25653,25653,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ وَهُوَ فِي ‏ ‏قُبَّةٍ ‏ ‏لَهُ فَوَجَدْتُهُ قَدْ ‏ ‏اغْتَسَلَ بِمَاءٍ كَانَ فِي ‏ ‏صَحْفَةٍ ‏ ‏إِنِّي لَأَرَى فِيهَا أَثَرَ الْعَجِينِ فَوَجَدْتُهُ ‏ ‏يُصَلِّي ضُحًى قُلْتُ ‏ ‏إِخَالُ ‏ ‏خَبَرَ ‏ ‏أُمِّ هَانِئٍ ‏ ‏هَذَا ‏ ‏ثَبَتَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏الضُّحَى ‏","","",""],[25654,25654,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏وَكَانَ نَازِلًا عَلَيْهَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ سُتِرَ عَلَيْهِ ‏ ‏فَاغْتَسَلَ فِي الضُّحَى فَصَلَّى ثَمَانِ رَكَعَاتٍ ‏ ‏لَا يُدْرَى أَقِيَامُهَا أَطْوَلُ أَمْ سُجُودُهَا ‏","","",""],[25655,25655,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏مَرَّةً وَلَهُ أَرْبَعُ ‏ ‏غَدَائِرَ ‏","","",""],[25656,25656,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَتْنِي ‏ ‏أُمُّ هَانِئٍ ‏ ‏فَقَالَتْ ‏ ‏لِي ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَوْلِهِ تَعَالَى ‏ { ‏وَتَأْتُونَ فِي ‏ ‏نَادِيكُمْ ‏ ‏الْمُنْكَرَ ‏} ‏قَالَ ‏ ‏كَانُوا ‏ ‏يَخْذِفُونَ ‏ ‏أَهْلَ الطَّرِيقِ وَيَسْخَرُونَ مِنْهُمْ فَذَاكَ الْمُنْكَرُ الَّذِي كَانُوا يَأْتُونَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فَذَلِكَ قَوْلُهُ تَعَالَى ‏ { ‏وَتَأْتُونَ فِي ‏ ‏نَادِيكُمْ ‏ ‏الْمُنْكَرَ ‏}","","",""],[25657,25657,"","","‏ ‏حَدَّثَنَا ‏ ‏زيدُ بْنُ الْحُبَابِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏فَاخِتَةَ أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏أَجَرْتُ ‏ ‏حَمْوَيْنِ لِي مِنْ الْمُشْرِكِينَ إِذْ طَلَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏رَهْجَةُ ‏ ‏الْغُبَارِ فِي ‏ ‏مِلْحَفَةٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهَا فَلَمَّا رَآنِي قَالَ مَرْحَبًا ‏ ‏بِفَاخِتَةَ أُمِّ هَانِئٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَجَرْتُ ‏ ‏حَمْوَيْنِ لِي مِنْ الْمُشْرِكِينَ فَقَالَ قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏وَأَمَّنَّا مَنْ أَمَّنْتِ ثُمَّ أَمَرَ ‏ ‏فَاطِمَةَ ‏ ‏فَسَكَبَتْ لَهُ مَاءً ‏ ‏فَتَغَسَّلَ بِهِ فَصَلَّى ثَمَانِ رَكَعَاتٍ فِي الثَّوْبِ ‏ ‏مُتَلَبِّبًا ‏ ‏بِهِ وَذَلِكَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏ضُحًى ‏","","",""],[25658,25658,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَعْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا ‏ ‏فَدَعَا بِشَرَابٍ فَشَرِبَ ثُمَّ نَاوَلَهَا فَشَرِبَتْ فَقَالَتْ يَا رَسُولَ اللَّهِ أَمَا إِنِّي كُنْتُ صَائِمَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّائِمُ الْمُتَطَوِّعُ أَمِيرُ نَفْسِهِ إِنْ شَاءَ صَامَ وَإِنْ شَاءَ أَفْطَرَ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ سَمِعْتَهُ أَنْتَ مِنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ لَا ‏ ‏حَدَّثَنِيهِ ‏ ‏أَبُو صَالِحٍ ‏ ‏وَأَهْلُنَا ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسْمَعُ ‏ ‏سِمَاكًا ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏ابْنَ أُمِّ هَانِئٍ ‏ ‏فَأَتَيْتُ أَنَا خَيْرَهُمَا وَأَفْضَلَهُمَا فَسَأَلْتُهُ وَكَانَ يُقَالُ لَهُ ‏ ‏جَعْدَةُ ‏","","",""],[25659,25659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ أَبُو زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالٌ يَعْنِي ابْنَ خَبَّابٍ ‏ ‏قَالَ ‏ ‏نَزَلْتُ أَنَا ‏ ‏وَمُجَاهِدٌ ‏ ‏عَلَى ‏ ‏يَحْيَى بْنِ جَعْدَةَ بْنِ أُمِّ هَانِئٍ ‏ ‏فَحَدَّثَنَا عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏أَنَا أَسْمَعُ قِرَاءَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏جَوْفِ ‏ ‏اللَّيْلِ وَأَنَا عَلَى ‏ ‏عَرِيشِي ‏ ‏هَذَا وَهُوَ عِنْدَ ‏ ‏الْكَعْبَةِ ‏","","",""],[25660,25660,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَابْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏اغْتَسَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَيْمُونَةُ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏قَصْعَةٍ ‏ ‏فِيهَا أَثَرُ الْعَجِينِ ‏","","",""],[25661,25661,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ رَأَيْتُ ‏ ‏أَبَا مُرَّةَ ‏ ‏وَكَانَ شَيْخًا قَدْ أَدْرَكَ ‏ ‏أُمَّ هَانِئٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فَقُلْتُ يَا رَسُولَ اللَّهِ قَدْ ‏ ‏أَجَرْتُ ‏ ‏حَمْوَيْنِ لِي فَزَعَمَ ابْنُ أُمِّي أَنَّهُ قَاتَلَهُ ‏ ‏تَعْنِي ‏ ‏عَلِيًّا ‏ ‏قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏وَصُبَّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاءٌ فَاغْتَسَلَ ثُمَّ ‏ ‏الْتَحَفَ ‏ ‏بِثَوْبٍ عَلَيْهِ وَخَالَفَ بَيْنَ طَرَفَيْهِ عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فَصَلَّى الضُّحَى ثَمَانِي رَكَعَاتٍ ‏","","",""],[25662,25662,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏حَتَّى قَعَدَتْ عَنْ يَسَارِهِ وَجَاءَتْ ‏ ‏أُمُّ هَانِئٍ ‏ ‏وَقَعَدَتْ عَنْ يَمِينِهِ وَجَاءَتْ ‏ ‏الْوَلِيدَةُ ‏ ‏بِشَرَابٍ فَتَنَاوَلَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَرِبَ ثُمَّ نَاوَلَهُ ‏ ‏أُمَّ هَانِئٍ ‏ ‏عَنْ يَمِينِهِ فَقَالَتْ لَقَدْ كُنْتُ صَائِمَةً فَقَالَ لَهَا ‏ ‏أَشَيْءٌ تَقْضِينَهُ عَلَيْكِ قَالَتْ لَا قَالَ لَا يَضُرُّكِ إِذًا ‏","","",""],[25663,25663,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏حَجَبُوهُ ‏ ‏وَأُتِيَ بِمَاءٍ ‏ ‏فَاغْتَسَلَ ثُمَّ صَلَّى الضُّحَى ‏ ‏ثَمَانِيَ رَكَعَاتٍ مَا رَآهُ أَحَدٌ بَعْدَهَا صَلَّاهَا ‏","","",""],[25664,25664,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى بَعْدَمَا ارْتَفَعَ النَّهَارُ يَوْمَ الْفَتْحِ ‏ ‏فَأَمَرَ بِثَوْبٍ فَسُتِرَ عَلَيْهِ فَاغْتَسَلَ ثُمَّ قَامَ فَرَكَعَ ‏ ‏ثَمَانِيَ رَكَعَاتٍ ‏ ‏لَا أَدْرِي أَقِيَامُهُ فِيهَا أَطْوَلُ أَوْ رُكُوعُهُ أَوْ سُجُودُهُ كُلُّ ذَلِكَ مِنْهُ مُتَقَارِبٌ ‏ ‏قَالَتْ فَلَمْ أَرَهُ سَبَّحَهَا قَبْلُ وَلَا بَعْدُ ‏","","",""],[25665,25665,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏مَا أَخْبَرَنِي أَحَدٌ أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى غَيْرَ ‏ ‏أُمِّ هَانِئٍ ‏ ‏فَإِنَّهَا حَدَّثَتْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ بَيْتَهَا يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏فَاغْتَسَلَ وَصَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ مَا رَأَتْهُ صَلَّى صَلَاةً قَطُّ أَخَفَّ مِنْهَا غَيْرَ أَنَّهُ كَانَ يُتِمُّ الرُّكُوعَ وَالسُّجُودَ ‏","","",""],[25666,25666,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ ‏ ‏عَنْ صَلَاةِ الضُّحَى فَقَالَ أَدْرَكْتُ ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ ‏ ‏مُتَوَافِرُونَ ‏ ‏فَمَا حَدَّثَنِي أَحَدٌ مِنْهُمْ أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى غَيْرَ ‏ ‏أُمِّ هَانِئٍ ‏ ‏فَإِنَّهَا قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ يَوْمَ جُمُعَةٍ ‏ ‏فَاغْتَسَلَ ثُمَّ صَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ ‏","","",""],[25667,25667,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ الْجَحْشِيِّ ‏ ‏عَنْ ‏ ‏مُوسَى ‏ ‏أَوْ ‏ ‏فُلَانِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخِذِي غَنَمًا يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَإِنَّهَا تَرُوحُ بِخَيْرٍ ‏ ‏وَتَغْدُو ‏ ‏بِخَيْرٍ ‏","","",""],[25668,25668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ الْمَخْزُومِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّهَا رَأَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ مُخَالِفًا بَيْنَ طَرَفَيْهِ ثَمَانِ رَكَعَاتٍ ‏ ‏بِمَكَّةَ ‏ ‏يَوْمَ الْفَتْحِ ‏","","",""],[25669,25669,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏لَمْ يُخْبِرْنَا أَحَدٌ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الضُّحَى إِلَّا ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَإِنَّهَا قَالَتْ ‏ ‏دَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتِي ‏ ‏فَاغْتَسَلَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏ثُمَّ صَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ يُخِفُّ فِيهِنَّ الرُّكُوعَ وَالسُّجُودَ ‏","","",""],[25670,25670,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَسْمَعُ قِرَاءَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ وَأَنَا عَلَى ‏ ‏عَرِيشِي ‏","","",""],[25671,25671,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏فَاخِتَةَ أُمِّ هَانِئٍ ‏ ‏عَنْ ‏ ‏فَاخِتَةَ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏أَجَرْتُ ‏ ‏رَجُلَيْنِ مِنْ ‏ ‏أَحْمَائِي ‏ ‏فَأَدْخَلْتُهُمَا بَيْتًا وَأَغْلَقْتُ عَلَيْهِمَا بَابًا فَجَاءَ ابْنُ أُمِّي ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏فَتَفَلَّتَ عَلَيْهِمَا بِالسَّيْفِ قَالَتْ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ أَجِدْهُ وَوَجَدْتُ ‏ ‏فَاطِمَةَ ‏ ‏فَكَانَتْ أَشَدَّ عَلَيَّ مِنْ زَوْجِهَا قَالَتْ فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ أَثَرُ الْغُبَارِ فَأَخْبَرْتُهُ فَقَالَ يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏وَأَمَّنَّا مَنْ أَمَّنْتِ ‏","","",""],[25672,25672,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّهَا ذَهَبَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ قَالَتْ فَوَجَدْتُهُ يَغْتَسِلُ ‏ ‏وَفَاطِمَةُ ‏ ‏تَسْتُرُهُ بِثَوْبٍ فَسَلَّمْتُ وَذَلِكَ ضُحًى فَقَالَ مَنْ هَذَا فَقُلْتُ أَنَا ‏ ‏أُمُّ هَانِئٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ زَعَمَ ابْنُ أُمِّي أَنَّهُ قَاتِلٌ رَجُلًا ‏ ‏أَجَرْتُهُ ‏ ‏فُلَانَ بْنَ هُبَيْرَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَجَرْنَا ‏ ‏مَنْ ‏ ‏أَجَرْتِ ‏ ‏يَا ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَلَمَّا فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غُسْلِهِ قَامَ فَصَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ مُلْتَحِفًا فِي ثَوْبٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَيْرِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أَبَا مُرَّةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏ذَهَبَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[25673,25673,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَعْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏وَهِيَ جَدَّتُهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا يَوْمَ الْفَتْحِ فَأُتِيَ بِشَرَابٍ فَشَرِبَ ثُمَّ نَاوَلَنِي فَقُلْتُ إِنِّي صَائِمَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُتَطَوِّعَ أَمِيرٌ عَلَى نَفْسِهِ فَإِنْ شِئْتِ فَصُومِي وَإِنْ شِئْتِ فَأَفْطِرِي ‏","","",""],[25674,25674,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏هَارُونَ ابْنِ بِنْتِ أُمِّ هَانِئٍ ‏ ‏أَوْ ‏ ‏ابْنِ أُمِّ هَانِئٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ شَرَابًا فَنَاوَلَهَا لِتَشْرَبَ فَقَالَتْ إِنِّي صَائِمَةٌ وَلَكِنْ كَرِهْتُ أَنْ أَرُدَّ ‏ ‏سُؤْرَكَ ‏ ‏فَقَالَ ‏ ‏يَعْنِي ‏ ‏إِنْ كَانَ قَضَاءً مِنْ رَمَضَانَ فَاقْضِي يَوْمًا مَكَانَهُ وَإِنْ كَانَ تَطَوُّعًا فَإِنْ شِئْتِ فَاقْضِي وَإِنْ شِئْتِ فَلَا تَقْضِي ‏","","",""],[25675,25675,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَلَفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏قَالَ قَالَتْ ‏ ‏مَرَّ بِي ذَاتَ يَوْمٍ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي قَدْ كَبِرْتُ وَضَعُفْتُ ‏ ‏أَوْ كَمَا قَالَتْ ‏ ‏فَمُرْنِي بِعَمَلٍ أَعْمَلُهُ وَأَنَا جَالِسَةٌ قَالَ ‏ ‏سَبِّحِي اللَّهَ مِائَةَ تَسْبِيحَةٍ فَإِنَّهَا تَعْدِلُ لَكِ مِائَةَ رَقَبَةٍ تُعْتِقِينَهَا مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَاحْمَدِي اللَّهَ مِائَةَ تَحْمِيدَةٍ تَعْدِلُ لَكِ مِائَةَ فَرَسٍ ‏ ‏مُسْرَجَةٍ ‏ ‏مُلْجَمَةٍ تَحْمِلِينَ عَلَيْهَا فِي سَبِيلِ اللَّهِ وَكَبِّرِي اللَّهَ مِائَةَ تَكْبِيرَةٍ فَإِنَّهَا تَعْدِلُ لَكِ مِائَةَ ‏ ‏بَدَنَةٍ ‏ ‏مُقَلَّدَةٍ ‏ ‏مُتَقَبَّلَةٍ وَهَلِّلِي ‏ ‏اللَّهَ مِائَةَ تَهْلِيلَةٍ ‏ ‏قَالَ ‏ ‏ابْنُ خَلَفٍ ‏ ‏أَحْسِبُهُ قَالَ تَمْلَأُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏ ‏وَلَا يُرْفَعُ يَوْمَئِذٍ لِأَحَدٍ عَمَلٌ إِلَّا أَنْ يَأْتِيَ بِمِثْلِ مَا أَتَيْتِ بِهِ ‏","","",""],[25676,25676,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ لِي إِلَّا مَا أَدْخَلَ ‏ ‏الزُّبَيْرُ ‏ ‏بَيْتِي قَالَ ‏ ‏أَنْفِقِي وَلَا ‏ ‏تُوكِي ‏ ‏فَيُوكَى ‏ ‏عَلَيْكِ ‏","","",""],[25677,25677,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏أَتَتْنِي ‏ ‏أُمِّي ‏ ‏رَاغِبَةً فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏وَهِيَ مُشْرِكَةٌ فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصِلُهَا قَالَ نَعَمْ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏مِثْلَهُ وَقَالَ وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏وَمُدَّتِهِمْ إِذْ عَاهَدُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25678,25678,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ ‏ ‏أُمِّي ‏ ‏وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏إِذْ عَاهَدُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ وَهِيَ ‏ ‏رَاغِبَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ صِلِي أُمَّكِ ‏","","",""],[25679,25679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجَّاجًا حَتَّى إِذَا كُنَّا ‏ ‏بِالْعَرْجِ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَلَسَتْ ‏ ‏عَائِشَةُ ‏ ‏إِلَى جَنْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَلَسْتُ إِلَى جَنْبِ أَبِي وَكَانَتْ زِمَالَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزِمَالَةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَاحِدَةً مَعَ غُلَامِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَجَلَسَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَنْتَظِرُهُ أَنْ يَطْلُعَ عَلَيْهِ فَطَلَعَ وَلَيْسَ مَعَهُ بَعِيرُهُ فَقَالَ أَيْنَ بَعِيرُكَ قَالَ قَدْ أَضْلَلْتُهُ الْبَارِحَةَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بَعِيرٌ وَاحِدٌ تُضِلُّهُ ‏ ‏فَطَفِقَ ‏ ‏يَضْرِبُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَبَسَّمُ وَيَقُولُ ‏ ‏انْظُرُوا إِلَى هَذَا الْمُحْرِمِ وَمَا يَصْنَعُ ‏","","",""],[25680,25680,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏أَفْرِدُوا بِالْحَجِّ وَدَعُوا قَوْلَ هَذَا ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ الْعَبَّاسِ ‏ ‏أَلَا تَسْأَلُ ‏ ‏أُمَّكَ ‏ ‏عَنْ هَذَا فَأَرْسَلَ إِلَيْهَا فَقَالَتْ صَدَقَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجَّاجًا ‏ ‏فَأَمَرَنَا فَجَعَلْنَاهَا عُمْرَةً ‏ ‏فَحَلَّ لَنَا الْحَلَالُ حَتَّى سَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏بَيْنَ النِّسَاءِ وَالرِّجَالِ ‏","","",""],[25681,25681,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي ابْنَةً عَرِيسًا وَإِنَّهُ أَصَابَتْهَا حَصْبَةٌ ‏ ‏فَتَمَرَّقَ ‏ ‏شَعْرُهَا ‏ ‏أَفَأَصِلُهُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25682,25682,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏نَحَرْنَا فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا فَأَكَلْنَا مِنْهُ ‏","","",""],[25683,25683,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ الْمَرْأَةُ يُصِيبُهَا مِنْ دَمِ حَيْضِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِتَحُتَّهُ ‏ ‏ثُمَّ ‏ ‏لِتَقْرِضْهُ ‏ ‏بِمَاءٍ ثُمَّ لِتُصَلِّي فِيهِ ‏","","",""],[25684,25684,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي عَلَى ضَرَّةٍ فَهَلْ عَلَيَّ جُنَاحٌ أَنْ أَتَشَبَّعَ مِنْ زَوْجِي بِمَا لَمْ يُعْطِنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ ‏ ‏زُورٍ ‏","","",""],[25685,25685,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْفَحِي ‏ ‏أَوْ ارْضَحِي أَوْ أَنْفِقِي وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25686,25686,"","","‏ ‏حَدَّثَنَا ‏ ‏عَثَّامُ بْنُ عَلِيٍّ أَبُو عَلِيٍّ الْعَامِرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏إِنْ ‏ ‏كُنَّا لَنُؤْمَرُ ‏ ‏بِالْعَتَاقَةِ ‏ ‏فِي صَلَاةِ الْخُسُوفِ ‏","","",""],[25687,25687,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏وَلَقَدْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَتَاقَةِ ‏ ‏فِي صَلَاةِ كُسُوفِ الشَّمْسِ ‏","","",""],[25688,25688,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏خَسَفَتْ ‏ ‏الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ مَا شَأْنُ النَّاسِ يُصَلُّونَ فَأَشَارَتْ بِرَأْسِهَا إِلَى السَّمَاءِ فَقُلْتُ ‏ ‏آيَةٌ ‏ ‏قَالَتْ نَعَمْ فَأَطَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِيَامَ جِدًّا حَتَّى ‏ ‏تَجَلَّانِي ‏ ‏الْغَشْيُ ‏ ‏فَأَخَذْتُ ‏ ‏قِرْبَةً ‏ ‏إِلَى جَنْبِي فَأَخَذْتُ أَصُبُّ عَلَى رَأْسِي الْمَاءَ فَانْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ ‏ ‏تَجَلَّتْ ‏ ‏الشَّمْسُ فَخَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏مَا مِنْ شَيْءٍ لَمْ أَكُنْ رَأَيْتُهُ إِلَّا قَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا حَتَّى الْجَنَّةُ وَالنَّارُ إِنَّهُ قَدْ أُوحِيَ إِلَيَّ أَنَّكُمْ ‏ ‏تُفْتَنُونَ ‏ ‏فِي الْقُبُورِ قَرِيبًا أَوْ مِثْلَ ‏ ‏فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏لَا أَدْرِي أَيَّ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏يُؤْتَى أَحَدُكُمْ فَيُقَالُ مَا عِلْمُكَ بِهَذَا الرَّجُلِ فَأَمَّا الْمُؤْمِنُ ‏ ‏أَوْ ‏ ‏الْمُوقِنُ ‏ ‏لَا أَدْرِي أَيَّ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏فَيَقُولُ هُوَ ‏ ‏مُحَمَّدٌ ‏ ‏هُوَ رَسُولُ اللَّهِ جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى فَأَجَبْنَا وَاتَّبَعْنَا ثَلَاثَ مِرَارٍ فَيُقَالُ لَهُ قَدْ كُنَّا نَعْلَمُ أَنْ كُنْتَ لَتُؤْمِنُ بِهِ فَنَمْ صَالِحًا وَأَمَّا الْمُنَافِقُ ‏ ‏أَوْ ‏ ‏الْمُرْتَابُ ‏ ‏لَا يَدْرِي أَيَّ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏فَيَقُولُ مَا أَدْرِي ‏ ‏سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُ ‏","","",""],[25689,25689,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏إِنَّهَا كَانَتْ إِذَا أُتِيَتْ بِالْمَرْأَةِ لِتَدْعُوَ لَهَا صَبَّتْ الْمَاءَ بَيْنَهَا وَبَيْنَ ‏ ‏جَيْبِهَا ‏ ‏وَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنَا أَنْ نُبْرِدَهَا بِالْمَاءِ وَقَالَ إِنَّهَا مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[25690,25690,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَفْطَرْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمِ ‏ ‏غَيْمٍ ‏ ‏فِي رَمَضَانَ ثُمَّ طَلَعَتْ الشَّمْسُ قُلْتُ ‏ ‏لِهِشَامٍ ‏ ‏أُمِرُوا بِالْقَضَاءِ قَالَ وَبُدٌّ مِنْ ذَاكَ ‏","","",""],[25691,25691,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَفَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏صَنَعْتُ ‏ ‏سُفْرَةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏أَبِي بَكْرٍ ‏ ‏حِينَ أَرَادَ أَنْ يُهَاجِرَ قَالَتْ فَلَمْ نَجِدْ ‏ ‏لِسُفْرَتِهِ ‏ ‏وَلَا ‏ ‏لِسِقَائِهِ ‏ ‏مَا نَرْبِطُهُمَا بِهِ قَالَتْ فَقُلْتُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَاللَّهِ مَا أَجِدُ شَيْئًا أَرْبِطُهُ بِهِ إِلَّا ‏ ‏نِطَاقِي ‏ ‏قَالَ فَقَالَ ‏ ‏شُقِّيهِ ‏ ‏بِاثْنَيْنِ فَارْبِطِي بِوَاحِدٍ ‏ ‏السِّقَاءَ ‏ ‏وَالْآخَرِ ‏ ‏السُّفْرَةَ ‏ ‏فَلِذَلِكَ سُمِّيَتْ ذَاتَ النِّطَاقَيْنِ ‏","","",""],[25692,25692,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي ضَرَّةً فَهَلْ عَلَيَّ ‏ ‏جُنَاحٌ ‏ ‏إِنْ تَشَبَّعْتُ مِنْ زَوْجِي بِغَيْرِ الَّذِي يُعْطِينِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ ‏ ‏زُورٍ ‏","","",""],[25693,25693,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَكَلْنَا لَحْمَ فَرَسٍ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25694,25694,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِي بُنَيَّةً عَرِيسًا وَإِنَّهُ ‏ ‏تَمَرَّقَ ‏ ‏شَعْرُهَا فَهَلْ عَلَيَّ ‏ ‏جُنَاحٌ ‏ ‏إِنْ وَصَلْتُ رَأْسَهَا قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25695,25695,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِحْدَانَا يُصِيبُ ثَوْبَهَا مِنْ دَمِ الْحَيْضَةِ قَالَتْ ‏ ‏تَحُتُّهُ ‏ ‏ثُمَّ ‏ ‏لِتَقْرُصْهُ ‏ ‏بِالْمَاءِ ثُمَّ ‏ ‏لِتَنْضَحْهُ ‏ ‏ثُمَّ تُصَلِّي فِيهِ ‏","","",""],[25696,25696,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏نَحَرْنَا فَرَسًا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكَلْنَا لَحْمَهُ ‏ ‏أَوْ مِنْ لَحْمِهِ ‏","","",""],[25697,25697,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي ‏ ‏أَوْ ‏ ‏ارْضَخِي ‏ ‏وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25698,25698,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏وَكَانَتْ ‏ ‏مُحْصِيَةً ‏ ‏وَعَنْ ‏ ‏عَبَّادِ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي أَوْ ‏ ‏انْضَخِي ‏ ‏أَوْ ‏ ‏انْفَحِي ‏ ‏هَكَذَا وَهَكَذَا وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعَى ‏ ‏عَلَيْكِ وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25699,25699,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏نُؤَدِّي زَكَاةَ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدَّيْنِ ‏ ‏مِنْ قَمْحٍ ‏ ‏بِالْمُدِّ ‏ ‏الَّذِي تَقْتَاتُونَ بِهِ ‏","","",""],[25700,25700,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏تَزَوَّجَنِي ‏ ‏الزُّبَيْرُ ‏ ‏وَمَا لَهُ فِي الْأَرْضِ مِنْ مَالٍ وَلَا مَمْلُوكٍ وَلَا شَيْءٍ غَيْرَ فَرَسِهِ قَالَتْ فَكُنْتُ أَعْلِفُ فَرَسَهُ ‏ ‏وَأَكْفِيهِ ‏ ‏مَئُونَتَهُ ‏ ‏وَأَسُوسُهُ ‏ ‏وَأَدُقُّ النَّوَى ‏ ‏لِنَاضِحِهِ ‏ ‏أَعْلِبُ ‏ ‏وَأَسْتَقِي الْمَاءَ ‏ ‏وَأَخْرُزُ ‏ ‏غَرْبَهُ ‏ ‏وَأَعْجِنُ وَلَمْ أَكُنْ أُحْسِنُ أَخْبِزُ فَكَانَ يَخْبِزُ لِي جَارَاتٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكُنَّ نِسْوَةَ صِدْقٍ وَكُنْتُ أَنْقُلُ النَّوَى مِنْ أَرْضِ ‏ ‏الزُّبَيْرِ ‏ ‏الَّتِي أَقْطَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَأْسِي وَهِيَ مِنِّي عَلَى ثُلُثَيْ ‏ ‏فَرْسَخٍ ‏ ‏قَالَتْ فَجِئْتُ يَوْمًا وَالنَّوَى عَلَى رَأْسِي فَلَقِيتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ ‏ ‏فَدَعَانِي ثُمَّ قَالَ ‏ ‏إِخْ ‏ ‏إِخْ ‏ ‏لِيَحْمِلَنِي خَلْفَهُ قَالَتْ فَاسْتَحَيْتُ أَنْ أَسِيرَ مَعَ الرِّجَالِ وَذَكَرْتُ ‏ ‏الزُّبَيْرَ ‏ ‏وَغَيْرَتَهُ قَالَتْ وَكَانَ أَغْيَرَ النَّاسِ فَعَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي قَدْ اسْتَحَيْتُ فَمَضَى وَجِئْتُ ‏ ‏الزُّبَيْرَ ‏ ‏فَقُلْتُ لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى رَأْسِي النَّوَى وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ ‏ ‏فَأَنَاخَ ‏ ‏لِأَرْكَبَ مَعَهُ فَاسْتَحَيْتُ وَعَرَفْتُ غَيْرَتَكَ فَقَالَ وَاللَّهِ لَحَمْلُكِ ‏ ‏النَّوَى ‏ ‏أَشَدُّ عَلَيَّ مِنْ رُكُوبِكِ مَعَهُ قَالَتْ حَتَّى أَرْسَلَ إِلَيَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏بَعْدَ ذَلِكَ بِخَادِمٍ فَكَفَتْنِي ‏ ‏سِيَاسَةَ ‏ ‏الْفَرَسِ فَكَأَنَّمَا أَعْتَقَنِي ‏","","",""],[25701,25701,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا حَمَلَتْ ‏ ‏بِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏بِمَكَّةَ ‏ ‏قَالَتْ فَخَرَجْتُ وَأَنَا مُتِمٌّ فَأَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَنَزَلْتُ ‏ ‏بِقُبَاءَ ‏ ‏فَوَلَدْتُهُ ‏ ‏بِقُبَاءَ ‏ ‏ثُمَّ أَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعْتُهُ فِي حِجْرِهِ ثُمَّ ‏ ‏دَعَا بِتَمْرَةٍ فَمَضَغَهَا ثُمَّ تَفَلَ فِي ‏ ‏فِيهِ فَكَانَ أَوَّلَ مَا دَخَلَ فِي جَوْفِهِ رِيقُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ثُمَّ ‏ ‏حَنَّكَهُ ‏ ‏بِتَمْرَةٍ ثُمَّ دَعَا لَهُ وَبَرَّكَ عَلَيْهِ وَكَانَ أَوَّلَ مَوْلُودٍ وُلِدَ فِي الْإِسْلَامِ ‏","","",""],[25702,25702,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَعْنِي عَبْدَ اللَّهِ بْنَ عَقِيلٍ الثَّقَفِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَيَّ ‏ ‏أُمِّي ‏ ‏فِي مُدَّةِ ‏ ‏قُرَيْشٍ ‏ ‏مُشْرِكَةً وَهِيَ ‏ ‏رَاغِبَةٌ ‏ ‏يَعْنِي مُحْتَاجَةٌ ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ عَلَيَّ وَهِيَ مُشْرِكَةٌ ‏ ‏رَاغِبَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏قَالَ ‏ ‏صِلِي ‏ ‏أُمَّكِ ‏","","",""],[25703,25703,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَيَّ ‏ ‏أُمِّي ‏ ‏وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏إِذْ عَاهَدُوا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ وَهِيَ ‏ ‏رَاغِبَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏قَالَ نَعَمْ ‏ ‏صِلِي ‏ ‏أُمَّكِ ‏","","",""],[25704,25704,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا نَزَلَتْ عِنْدَ دَارِ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فَقَالَتْ أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ لَيْلَةَ ‏ ‏جَمْعٍ ‏ ‏وَهِيَ تُصَلِّي قُلْتُ لَا فَصَلَّتْ سَاعَةً ثُمَّ قَالَتْ أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ قَالَ وَقَدْ غَابَ الْقَمَرُ قُلْتُ نَعَمْ قَالَتْ فَارْتَحِلُوا فَارْتَحَلْنَا ثُمَّ مَضَيْنَا بِهَا حَتَّى رَمَيْنَا الْجَمْرَةَ ثُمَّ رَجَعَتْ فَصَلَّتْ الصُّبْحَ فِي مَنْزِلِهَا فَقُلْتُ لَهَا أَيْ ‏ ‏هَنْتَاهُ ‏ ‏لَقَدْ غَلَّسْنَا قَالَتْ كَلَّا يَا بُنَيَّ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ ‏ ‏لِلظُّعُنِ ‏","","",""],[25705,25705,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَ ‏ ‏أَخْرَجَتْ إِلَيَّ ‏ ‏جُبَّةً ‏ ‏طَيَالِسَةً ‏ ‏عَلَيْهَا ‏ ‏لَبِنَةُ ‏ ‏شَبْرٍ ‏ ‏مِنْ ‏ ‏دِيبَاجٍ ‏ ‏كِسْرَوَانِيٍّ ‏ ‏وَفَرْجَاهَا ‏ ‏مَكْفُوفَانِ ‏ ‏بِهِ قَالَتْ هَذِهِ ‏ ‏جُبَّةُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْبَسُهَا كَانَتْ عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَلَمَّا قُبِضَتْ ‏ ‏عَائِشَةُ ‏ ‏قَبَضْتُهَا إِلَيَّ فَنَحْنُ نَغْسِلُهَا لِلْمَرِيضِ مِنَّا ‏ ‏يَسْتَشْفِي بِهَا ‏","","",""],[25706,25706,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ يَزِيدَ الْعَطَّارِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا شَيْءَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25707,25707,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏قَالَ ‏ ‏أَخْرَجَتْ إِلَيْنَا ‏ ‏أَسْمَاءُ ‏ ‏جُبَّةً ‏ ‏مَزْرُورَةً ‏ ‏بِالدِّيبَاجِ ‏ ‏فَقَالَتْ فِي هَذِهِ كَانَ يَلْقَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَدُوَّ ‏","","",""],[25708,25708,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُبَّةٌ مِنْ ‏ ‏طَيَالِسَةٍ ‏ ‏لَبِنَتُهَا ‏ ‏دِيبَاجٌ ‏ ‏كِسْرَوَانِيٌّ ‏","","",""],[25709,25709,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْقُرِّيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مُتْعَةِ ‏ ‏الْحَجِّ فَرَخَّصَ فِيهَا وَكَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَنْهَى عَنْهَا فَقَالَ هَذِهِ ‏ ‏أُمُّ ابْنِ الزُّبَيْرِ ‏ ‏تُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِيهَا فَادْخُلُوا عَلَيْهَا فَاسْأَلُوهَا قَالَ فَدَخَلْنَا عَلَيْهَا فَإِذَا امْرَأَةٌ ضَخْمَةٌ عَمْيَاءُ فَقَالَتْ ‏ ‏قَدْ رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏","","",""],[25710,25710,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُسْلِمٍ ‏ ‏أَخُو ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَوْلَى لِأَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا تَرْفَعْ رَأْسَهَا حَتَّى نَرْفَعَ رُءُوسَنَا كَرَاهَةَ أَنْ يَرَيْنَ عَوْرَاتِ الرِّجَالِ لِصِغَرِ ‏ ‏أُزُرِهِمْ ‏ ‏وَكَانُوا إِذْ ذَاكَ ‏ ‏يَأْتَزِرُونَ ‏ ‏بِهَذِهِ النَّمِرَةِ ‏","","",""],[25711,25711,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏بَعْضِهِمْ ‏ ‏عَنْ ‏ ‏مَوْلَى لِأَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ الْمُسْلِمُونَ ‏ ‏ذَوِي ‏ ‏حَاجَةٍ ‏ ‏يَأْتَزِرُونَ ‏ ‏بِهَذِهِ ‏ ‏النَّمِرَةِ ‏ ‏فَكَانَتْ إِنَّمَا تَبْلُغُ أَنْصَافَ سُوقِهِمْ ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏ ‏فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏يَعْنِي النِّسَاءَ ‏ ‏فَلَا تَرْفَعْ رَأْسَهَا حَتَّى نَرْفَعَ رُءُوسَنَا كَرَاهِيَةَ أَنْ تَنْظُرَ إِلَى عَوْرَاتِ الرِّجَالِ مِنْ صِغَرِ ‏ ‏أُزُرِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُسْلِمِ بْنِ شِهَابٍ ‏ ‏أَخِي ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[25712,25712,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏النُّعْمَانُ بْنُ رَاشِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَوْلًى لِأَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ النِّسَاءِ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا تَرْفَعْ رَأْسَهَا حَتَّى يَرْفَعَ الرِّجَالُ رُءُوسَهُمْ قَالَتْ وَذَلِكَ أَنَّ ‏ ‏أُزُرَهُمْ ‏ ‏كَانَتْ قَصِيرَةً مَخَافَةَ أَنْ تَنْكَشِفَ عَوْرَاتُهُمْ إِذَا سَجَدُوا ‏","","",""],[25713,25713,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ النِّسَاءِ ‏ ‏مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا تَرْفَعْ رَأْسَهَا حَتَّى يَرْفَعَ الْإِمَامُ رَأْسَهُ مِنْ ضِيقِ ثِيَابِ الرِّجَالِ ‏","","",""],[25714,25714,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏حَجَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنَا فَجَعَلْنَاهَا عُمْرَةً فَأَحْلَلْنَا كُلَّ الْإِحْلَالِ حَتَّى سَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏بَيْنَ النِّسَاءِ وَالرِّجَالِ ‏","","",""],[25715,25715,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ فَمَا أَدْرِي ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏أَوْ ‏ ‏سُعْدَى بِنْتَ عَوْفٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏ضُبَاعَةَ بِنْتِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ ‏ ‏مَا يَمْنَعُكَ مِنْ الْحَجِّ يَا عَمَّةُ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي امْرَأَةٌ ‏ ‏سَقِيمَةٌ ‏ ‏وَإِنِّي أَخَافُ ‏ ‏الْحَبْسَ ‏ ‏قَالَ فَأَحْرِمِي وَاشْتَرِطِي أَنَّ مَحِلَّكِ حَيْثُ ‏ ‏حُبِسْتِ ‏","","",""],[25716,25716,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏فَزِعَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ كَسَفَتْ الشَّمْسُ ‏ ‏فَأَخَذَ ‏ ‏دِرْعًا ‏ ‏حَتَّى ‏ ‏أَدْرَكَ ‏ ‏بِرِدَائِهِ فَقَامَ بِالنَّاسِ ‏ ‏قِيَامًا ‏ ‏طَوِيلًا يَقُومُ ثُمَّ يَرْكَعُ قَالَتْ فَجَعَلْتُ أَنْظُرُ إِلَى الْمَرْأَةِ الَّتِي هِيَ أَكْبَرُ مِنِّي قَائِمَةً وَإِلَى الْمَرْأَةِ الَّتِي هِيَ ‏ ‏أَسْقَمُ ‏ ‏مِنِّي قَائِمَةً فَقُلْتُ إِنِّي أَحَقُّ أَنْ أَصْبِرَ عَلَى طُولِ الْقِيَامِ مِنْكِ ‏ ‏و قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَزِعَ ‏","","",""],[25717,25717,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَقْرَأُ وَهُوَ ‏ ‏يُصَلِّي نَحْوَ الرُّكْنِ قَبْلَ أَنْ ‏ ‏يَصْدَعَ ‏ ‏بِمَا يُؤْمَرُ وَالْمُشْرِكُونَ يَسْتَمِعُونَ ‏ { ‏فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ‏}","","",""],[25718,25718,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذِي طُوًى ‏ ‏قَالَ ‏ ‏أَبُو قُحَافَةَ ‏ ‏لِابْنَةٍ لَهُ مِنْ أَصْغَرِ وَلَدِهِ أَيْ بُنَيَّةُ اظْهَرِي بِي عَلَى ‏ ‏أَبِي قَبِيسٍ ‏ ‏قَالَتْ وَقَدْ كُفَّ بَصَرُهُ قَالَتْ ‏ ‏فَأَشْرَفْتُ ‏ ‏بِهِ عَلَيْهِ فَقَالَ يَا بُنَيَّةُ مَاذَا تَرَيْنَ قَالَتْ أَرَى سَوَادًا مُجْتَمِعًا قَالَ تِلْكَ الْخَيْلُ قَالَتْ وَأَرَى رَجُلًا ‏ ‏يَسْعَى ‏ ‏بَيْنَ ذَلِكَ ‏ ‏السَّوَادِ ‏ ‏مُقْبِلًا ‏ ‏وَمُدْبِرًا ‏ ‏قَالَ يَا بُنَيَّةُ ذَلِكَ الْوَازِعُ ‏ ‏يَعْنِي الَّذِي يَأْمُرُ الْخَيْلَ وَيَتَقَدَّمُ إِلَيْهَا ‏ ‏ثُمَّ قَالَتْ قَدْ وَاللَّهِ انْتَشَرَ ‏ ‏السَّوَادُ ‏ ‏فَقَالَ قَدْ وَاللَّهِ إِذَا دَفَعَتْ الْخَيْلُ فَأَسْرِعِي بِي إِلَى بَيْتِي ‏ ‏فَانْحَطَّتْ ‏ ‏بِهِ وَتَلَقَّاهُ الْخَيْلُ قَبْلَ أَنْ يَصِلَ إِلَى بَيْتِهِ وَفِي عُنُقِ ‏ ‏الْجَارِيَةِ ‏ ‏طَوْقٌ لَهَا مِنْ وَرِقٍ فَتَلَقَّاهُ الرَّجُلُ فَاقْتَلَعَهُ مِنْ عُنُقِهَا قَالَتْ فَلَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏وَدَخَلَ الْمَسْجِدَ أَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِأَبِيهِ يَعُودُهُ فَلَمَّا رَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَلَّا تَرَكْتَ الشَّيْخَ فِي بَيْتِهِ حَتَّى أَكُونَ أَنَا آتِيهِ فِيهِ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ هُوَ أَحَقُّ أَنْ يَمْشِيَ إِلَيْكَ مِنْ أَنْ تَمْشِيَ أَنْتَ إِلَيْهِ قَالَ فَأَجْلَسَهُ بَيْنَ يَدَيْهِ ثُمَّ مَسَحَ صَدْرَهُ ثُمَّ قَالَ لَهُ ‏ ‏أَسْلِمْ فَأَسْلَمَ وَدَخَلَ بِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأْسُهُ كَأَنَّهُ ‏ ‏ثَغَامَةٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيِّرُوا هَذَا مِنْ شَعْرِهِ ثُمَّ قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَأَخَذَ بِيَدِ أُخْتِهِ فَقَالَ أَنْشُدُ ‏ ‏بِاللَّهِ وَبِالْإِسْلَامِ طَوْقَ أُخْتِي فَلَمْ يُجِبْهُ أَحَدٌ فَقَالَ يَا ‏ ‏أُخَيَّةُ احْتَسِبِي طَوْقَكِ ‏","","",""],[25719,25719,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏جَدَّتِهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجَ مَعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏احْتَمَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَالَهُ كُلَّهُ مَعَهُ خَمْسَةَ آلَافِ دِرْهَمٍ ‏ ‏أَوْ سِتَّةَ آلَافِ دِرْهَمٍ ‏ ‏قَالَتْ وَانْطَلَقَ بِهَا مَعَهُ قَالَتْ فَدَخَلَ عَلَيْنَا جَدِّي ‏ ‏أَبُو قُحَافَةَ ‏ ‏وَقَدْ ذَهَبَ بَصَرُهُ فَقَالَ وَاللَّهِ إِنِّي لَأَرَاهُ قَدْ ‏ ‏فَجَعَكُمْ ‏ ‏بِمَالِهِ مَعَ نَفْسِهِ قَالَتْ قُلْتُ كَلَّا يَا ‏ ‏أَبَتِ إِنَّهُ قَدْ تَرَكَ لَنَا خَيْرًا كَثِيرًا قَالَتْ فَأَخَذْتُ أَحْجَارًا فَتَرَكْتُهَا فَوَضَعْتُهَا فِي ‏ ‏كُوَّةِ ‏ ‏الْبَيْتِ كَانَ أَبِي يَضَعُ فِيهَا مَالَهُ ثُمَّ وَضَعْتُ عَلَيْهَا ثَوْبًا ثُمَّ أَخَذْتُ بِيَدِهِ فَقُلْتُ يَا ‏ ‏أَبَتِ ضَعْ يَدَكَ عَلَى هَذَا الْمَالِ قَالَتْ فَوَضَعَ يَدَهُ عَلَيْهِ فَقَالَ لَا بَأْسَ إِنْ كَانَ قَدْ تَرَكَ لَكُمْ هَذَا فَقَدْ أَحْسَنَ وَفِي هَذَا لَكُمْ ‏ ‏بَلَاغٌ ‏ ‏قَالَتْ لَا وَاللَّهِ مَا تَرَكَ لَنَا شَيْئًا وَلَكِنِّي قَدْ ‏ ‏أَرَدْتُ ‏ ‏أَنْ أُسْكِنَ الشَّيْخَ بِذَلِكَ ‏","","",""],[25720,25720,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏إِذَا ‏ ‏ثَرَدَتْ ‏ ‏غَطَّتْهُ شَيْئًا حَتَّى يَذْهَبَ فَوْرُهُ ثُمَّ تَقُولُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ أَعْظَمُ لِلْبَرَكَةِ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏و حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا كَانَتْ إِذَا ثَرَدَتْ غَطَّتْهُ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25721,25721,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ يَزِيدَ الْقَطَّانُ بَصْرِيٌّ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي زَوَّجْتُ ابْنَتِي فَمَرِضَتْ ‏ ‏فَتَمَرَّطَ ‏ ‏رَأْسُهَا وَإِنَّ زَوْجَهَا قَدْ اخْتَلَفَ إِلَيَّ ‏ ‏أَفَأَصِلُ ‏ ‏رَأْسَهَا قَالَتْ فَسَبَّ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25722,25722,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنِ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَقَالَتْ فَقَالَ لَنَا ‏ ‏مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَقُمْ عَلَى إِحْرَامِهِ وَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَحْلِلْ ‏","","",""],[25723,25723,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَادَةَ بْنَ الْمُهَاجِرِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ الْعَبَّاسِ ‏ ‏يَقُولُ ‏ ‏لِابْنِ الزُّبَيْرِ ‏ ‏أَلَا تَسْأَلُ أُمَّكَ قَالَ فَدَخَلْنَا عَلَى أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏فَقَالَتْ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏قَالَ ‏ ‏مَنْ أَرَادَ مِنْكُمْ أَنْ ‏ ‏يُهِلَّ ‏ ‏بِالْحَجِّ ‏ ‏فَلْيُهِلَّ ‏ ‏وَمَنْ أَرَادَ مِنْكُمْ أَنْ ‏ ‏يُهِلَّ ‏ ‏بِعُمْرَةٍ ‏ ‏فَلْيُهِلَّ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏وَكُنْتُ أَنَا ‏ ‏وَعَائِشَةُ ‏ ‏وَالْمِقْدَادُ ‏ ‏وَالزُّبَيْرُ ‏ ‏مِمَّنْ أَهَلَّ بِعُمْرَةٍ ‏","","",""],[25724,25724,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْكُسُوفِ قَالَتْ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ سَجَدَ ‏ ‏فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقَيَّامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ انْصَرَفَ فَقَالَ ‏ ‏دَنَتْ ‏ ‏مِنِّي الْجَنَّةُ حَتَّى لَوْ ‏ ‏اجْتَرَأْتُ ‏ ‏لَجِئْتُكُمْ ‏ ‏بِقِطَافٍ ‏ ‏مِنْ قِطَافِهَا ‏ ‏وَدَنَتْ ‏ ‏مِنِّي النَّارُ حَتَّى قُلْتُ يَا رَبُّ وَأَنَا مَعَهُمْ وَإِذَا امْرَأَةٌ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ تَخْدِشُهَا هِرَّةٌ ‏ ‏قُلْتُ مَا شَأْنُ هَذِهِ قِيلَ لِي حَبَسَتْهَا حَتَّى مَاتَتْ لَا هِيَ أَطْعَمَتْهَا وَلَا هِيَ أَرْسَلَتْهَا تَأْكُلُ مِنْ ‏ ‏خِشَاشِ ‏ ‏الْأَرْضِ ‏","","",""],[25725,25725,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُمَرَ الْجُمَحِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ فَصَلَّى فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ فَعَلَ فِي الثَّانِيَةِ مِثْلَ ذَلِكَ ثُمَّ قَالَ لَقَدْ ‏ ‏أُدْنِيَتْ ‏ ‏مِنِّي الْجَنَّةُ حَتَّى لَوْ ‏ ‏اجْتَرَأْتُ ‏ ‏عَلَيْهَا لَأَتَيْتُكُمْ ‏ ‏بِقِطْفٍ ‏ ‏مِنْ ‏ ‏أَقْطَافِهَا ‏ ‏وَلَقَدْ ‏ ‏أُدْنِيَتْ ‏ ‏مِنِّي النَّارُ حَتَّى قُلْتُ يَا رَبُّ وَأَنَا مَعَهُمْ فَرَأَيْتُ فِيهَا هِرَّةً ‏ ‏قَالَ حَسِبْتُ أَنَّهَا تَخْدِشُ امْرَأَةً ‏ ‏حَبَسَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ ‏ ‏خِشَاشِ ‏ ‏الْأَرْضِ حَتَّى مَاتَتْ ‏","","",""],[25726,25726,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏وَهِيَ أُمُّهُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مُحْرِمِينَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيُتِمَّ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏فَلْيَقُمْ ‏ ‏عَلَى إِحْرَامِهِ وَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَحْلِلْ ‏ ‏قَالَتْ ‏ ‏فَلَمْ يَكُنْ مَعِي ‏ ‏هَدْيٌ ‏ ‏فَحَلَلْتُ وَكَانَ مَعَ ‏ ‏الزُّبَيْرِ ‏ ‏زَوْجِهَا ‏ ‏هَدْيٌ ‏ ‏فَلَمْ ‏ ‏يَحِلَّ ‏ ‏قَالَتْ فَلَبِسْتُ ثِيَابِي وَحَلَلْتُ فَجِئْتُ إِلَى ‏ ‏الزُّبَيْرِ ‏ ‏فَقَالَ قُومِي عَنِّي قَالَتْ فَقُلْتُ ‏ ‏أَتَخْشَى أَنْ ‏ ‏أَثِبَ ‏ ‏عَلَيْكَ ‏","","",""],[25727,25727,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ مَوْلَى أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ لَيْلَةَ ‏ ‏جَمْعٍ ‏ ‏قُلْتُ لَا ثُمَّ قَالَتْ أَيْ بُنَيَّ هَلْ غَابَ الْقَمَرُ قُلْتُ نَعَمْ قَالَتْ فَارْتَحِلُوا فَارْتَحَلْنَا ثُمَّ مَضَيْنَا حَتَّى رَمَتْ الْجَمْرَةَ ثُمَّ رَجَعَتْ فَصَلَّتْ الصُّبْحَ فِي مَنْزِلِهَا فَقُلْتُ لَهَا لَقَدْ غَلَّسْنَا ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏أَيْ ‏ ‏هَنْتَاهُ ‏ ‏قَالَتْ كَلَّا يَا بُنَيَّ ‏ ‏إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ ‏ ‏لِلظُّعُنِ ‏","","",""],[25728,25728,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏أَنَّ ‏ ‏الْحَجَّاجَ بْنَ يُوسُفَ ‏ ‏دَخَلَ عَلَى ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏بَعْدَمَا قُتِلَ ابْنُهَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏فَقَالَ إِنَّ ابْنَكِ ‏ ‏أَلْحَدَ ‏ ‏فِي هَذَا الْبَيْتِ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَذَاقَهُ مِنْ عَذَابٍ أَلِيمٍ وَفَعَلَ بِهِ مَا فَعَلَ فَقَالَتْ كَذَبْتَ كَانَ بَرًّا بِالْوَالِدَيْنِ ‏ ‏صَوَّامًا ‏ ‏قَوَّامًا ‏ ‏وَاللَّهِ لَقَدْ أَخْبَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَيَخْرُجُ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابَانِ الْآخِرُ مِنْهُمَا شَرٌّ مِنْ الْأَوَّلِ وَهُوَ ‏ ‏مُبِيرٌ ‏","","",""],[25729,25729,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏فَزِعَ ‏ ‏يَوْمَ كَسَفَتْ الشَّمْسُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ ‏ ‏دِرْعًا ‏ ‏حَتَّى أَدْرَكَ بِرِدَائِهِ فَقَامَ بِالنَّاسِ قِيَامًا طَوِيلًا يَقُومُ ثُمَّ يَرْكَعُ فَلَوْ جَاءَ إِنْسَانٌ بَعْدَمَا رَكَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَعْلَمْ أَنَّهُ رَكَعَ مَا حَدَّثَ نَفْسَهُ أَنَّهُ رَكَعَ مِنْ طُولِ الْقِيَامِ قَالَتْ فَجَعَلْتُ أَنْظُرُ إِلَى الْمَرْأَةِ الَّتِي هِيَ أَكْبَرُ مِنِّي وَإِلَى الْمَرْأَةِ الَّتِي هِيَ ‏ ‏أَسْقَمُ ‏ ‏مِنِّي قَائِمَةً وَأَنَا أَحَقُّ أَنْ أَصْبِرَ عَلَى طُولِ الْقِيَامِ مِنْهَا ‏","","",""],[25730,25730,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏وَأَبَانُ بْنُ يَزِيدَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏أَخْبَرَتْهُ أَنَّهَا ‏ ‏سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ إِنَّهُ ‏ ‏لَيْسَ شَيْءٌ أَغْيَرَ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبَانَ ‏ ‏لَا شَيْءَ أَغْيَرَ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25731,25731,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُحْصِي شَيْئًا وَأَكِيلُهُ قَالَ يَا ‏ ‏أَسْمَاءُ ‏ ‏لَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ قَالَتْ فَمَا ‏ ‏أَحْصَيْتُ ‏ ‏شَيْئًا بَعْدَ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ عِنْدِي وَلَا دَخَلَ عَلَيَّ وَمَا نَفِدَ عِنْدِي مِنْ رِزْقِ اللَّهِ إِلَّا أَخْلَفَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[25732,25732,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي مُعَاوِيَةُ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ ‏ ‏مَا مِنْ شَيْءٍ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25733,25733,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَخْدُمُ ‏ ‏الزُّبَيْرَ ‏ ‏زَوْجَهَا وَكَانَ لَهُ فَرَسٌ كُنْتُ ‏ ‏أَسُوسُهُ ‏ ‏وَلَمْ يَكُنْ شَيْءٌ مِنْ الْخِدْمَةِ أَشَدَّ عَلَيَّ مِنْ ‏ ‏سِيَاسَةِ ‏ ‏الْفَرَسِ فَكُنْتُ ‏ ‏أَحْتَشُّ ‏ ‏لَهُ وَأَقُومُ عَلَيْهِ ‏ ‏وَأَسُوسُهُ ‏ ‏وَأَرْضَخُ ‏ ‏لَهُ ‏ ‏النَّوَى ‏ ‏قَالَ ثُمَّ ‏ ‏إِنَّهَا أَصَابَتْ خَادِمًا أَعْطَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَكَفَتْنِي ‏ ‏سِيَاسَةَ ‏ ‏الْفَرَسِ فَأَلْقَتْ عَنِّي ‏ ‏مَئُونَتَهُ ‏","","",""],[25734,25734,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ ‏ ‏لَا شَيْءَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[25735,25735,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي هَذَا الْحَدِيثَ بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ سُلَيْمَانَ سَعْدَوَيْهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏هَارُونَ بْنِ عَنْتَرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا قَتَلَ ‏ ‏الْحَجَّاجُ بْنَ الزُّبَيْرِ ‏ ‏وَصَلَبَهُ مَنْكُوسًا فَبَيْنَا هُوَ عَلَى الْمِنْبَرِ إِذْ جَاءَتْ ‏ ‏أَسْمَاءُ ‏ ‏وَمَعَهَا أَمَةٌ تَقُودُهَا وَقَدْ ذَهَبَ بَصَرُهَا فَقَالَتْ أَيْنَ أَمِيرُكُمْ فَذَكَرَ قِصَّةً فَقَالَتْ كَذَبْتَ وَلَكِنِّي أُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابَانِ الْآخِرُ مِنْهُمَا أَشَرُّ مِنْ الْأَوَّلِ وَهُوَ ‏ ‏مُبِيرٌ ‏","","",""],[25736,25736,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ ‏ ‏تَقُولُ ‏ ‏عِنْدِي ‏ ‏لِلزُّبَيْرِ ‏ ‏سَاعِدَانِ ‏ ‏مِنْ ‏ ‏دِيبَاجٍ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَاهُمَا إِيَّاهُ يُقَاتِلُ فِيهِمَا ‏","","",""],[25737,25737,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ الْمُنْكَدِرِ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏أَسْمَاءُ ‏ ‏تُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ قَالَ ‏ ‏إِذَا دَخَلَ الْإِنْسَانُ قَبْرَهُ فَإِنْ كَانَ مُؤْمِنًا ‏ ‏أَحَفَّ ‏ ‏بِهِ عَمَلُهُ الصَّلَاةُ وَالصِّيَامُ قَالَ فَيَأْتِيهِ الْمَلَكُ مِنْ نَحْوِ الصَّلَاةِ فَتَرُدُّهُ وَمِنْ نَحْوِ الصِّيَامِ فَيَرُدُّهُ قَالَ ‏ ‏فَيُنَادِيهِ اجْلِسْ قَالَ فَيَجْلِسُ فَيَقُولُ لَهُ مَاذَا تَقُولُ فِي هَذَا الرَّجُلِ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ أَنَا أَشْهَدُ أَنَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ وَمَا يُدْرِيكَ أَدْرَكْتَهُ أَشْهَدُ أَنَّهُ رَسُولُ اللَّهِ قَالَ يَقُولُ عَلَى ذَلِكَ عِشْتَ وَعَلَيْهِ مِتَّ وَعَلَيْهِ تُبْعَثُ قَالَ وَإِنْ كَانَ فَاجِرًا أَوْ كَافِرًا قَالَ جَاءَ الْمَلَكُ وَلَيْسَ بَيْنَهُ وَبَيْنَهُ شَيْءٌ يَرُدُّهُ قَالَ فَأَجْلَسَهُ قَالَ يَقُولُ اجْلِسْ مَاذَا تَقُولُ فِي هَذَا الرَّجُلِ قَالَ أَيُّ رَجُلٍ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ يَقُولُ وَاللَّهِ مَا أَدْرِي سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ قَالَ فَيَقُولُ لَهُ الْمَلَكُ عَلَى ذَلِكَ عِشْتَ وَعَلَيْهِ مِتَّ وَعَلَيْهِ تُبْعَثُ قَالَ وَتُسَلَّطُ عَلَيْهِ دَابَّةٌ فِي قَبْرِهِ مَعَهَا سَوْطٌ تَمْرَتُهُ جَمْرَةٌ مِثْلُ ‏ ‏غَرْبِ ‏ ‏الْبَعِيرِ تَضْرِبُهُ مَا شَاءَ اللَّهُ ‏ ‏صَمَّاءُ ‏ ‏لَا تَسْمَعُ صَوْتَهُ فَتَرْحَمَهُ ‏","","",""],[25738,25738,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏ضَرَّةً ‏ ‏فَهَلْ عَلَيَّ ‏ ‏جُنَاحٌ ‏ ‏إِنْ تَشَبَّعْتُ مِنْ زَوْجِي بِغَيْرِ الَّذِي يُعْطِينِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَهُ كَلَابِسِ ثَوْبَيْ ‏ ‏زُورٍ ‏","","",""],[25739,25739,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَكَلْنَا فَرَسًا لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25740,25740,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ بِنْتُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِي بُنَيَّةً عَرِيسًا وَإِنَّهُ ‏ ‏تَمَرَّقَ ‏ ‏شَعَرُهَا فَهَلْ عَلَيَّ مِنْ ‏ ‏جُنَاحٍ ‏ ‏إِنْ ‏ ‏وَصَلْتُ ‏ ‏رَأْسَهَا ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏تَمَرَّطَ ‏ ‏شَعْرُهَا ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[25741,25741,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ لَيْسَ لِي إِلَّا مَا أَدْخَلَ عَلَيَّ ‏ ‏الزُّبَيْرُ ‏ ‏أَفَأَرْضَخُ ‏ ‏مِنْهُ قَالَ ‏ ‏ارْضَخِي ‏ ‏وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25742,25742,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏فَاطِمَةُ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِحْدَانَا يُصِيبُ ثَوْبُهَا مِنْ دَمِ الْحَيْضَةِ قَالَ ‏ ‏تَحُتُّهُ ‏ ‏ثُمَّ ‏ ‏لِتَقْرِضْهُ ‏ ‏بِالْمَاءِ ثُمَّ ‏ ‏تَنْضَحْهُ ‏ ‏ثُمَّ تُصَلِّي فِيهِ ‏","","",""],[25743,25743,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏يَا جَارِيَةُ ‏ ‏نَاوِلِينِي ‏ ‏جُبَّةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَخْرَجَتْ ‏ ‏جُبَّةً ‏ ‏مِنْ ‏ ‏طَيَالِسَةٍ ‏","","",""],[25744,25744,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏نَحَرْنَا ‏ ‏فَرَسًا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكَلْنَا لَحْمَهُ ‏ ‏أَوْ مِنْ لَحْمِهِ ‏","","",""],[25745,25745,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ ‏ ‏وَعَبْدُ الْجَبَّارِ بْنُ وَرْدٍ ‏ ‏رَجُلَانِ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏سَمِعَاهُ مِنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرِ ‏ ‏رَجُلٌ شَدِيدٌ ‏ ‏وَيَأْتِينِي الْمِسْكِينُ فَأَتَصَدَّقُ عَلَيْهِ مِنْ بَيْتِهِ بِغَيْرِ إِذْنِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْضَخِي ‏ ‏وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25746,25746,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25747,25747,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏مَوْلَى ‏ ‏أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ لَهُ ‏ ‏جُبَّةٌ ‏ ‏مِنْ ‏ ‏طَيَالِسَةٍ ‏ ‏مَكْفُوفَةٍ ‏ ‏بِالدِّيبَاجِ ‏ ‏يَلْقَى فِيهَا الْعَدُوَّ ‏","","",""],[25748,25748,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا لِي شَيْءٌ إِلَّا مَا أَدْخَلَ ‏ ‏الزُّبَيْرُ ‏ ‏عَلَى بَيْتِي ‏ ‏فَأُعْطِي مِنْهُ قَالَ ‏ ‏أَعْطِي وَلَا ‏ ‏تُوكِي ‏ ‏فَيُوكِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏عَبَّادَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏نَحْوَهُ ‏","","",""],[25749,25749,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏مَوْلَى أَسْمَاءَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُبَّةٌ ‏ ‏مِنْ ‏ ‏طَيَالِسَةٍ ‏ ‏لَبِنَتُهَا ‏ ‏دِيبَاجٌ ‏ ‏كِسْرَوَانِيٌّ ‏","","",""],[25750,25750,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي ‏ ‏أَوْ ‏ ‏انْضَحِي ‏ ‏وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏ ‏أَوْ لَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25751,25751,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏وَكَانَتْ ‏ ‏مُحْصِيَةً ‏ ‏وَعَنِ ‏ ‏عَبَّادِ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏أَنْفِقِي أَوْ ‏ ‏انْضَخِي ‏ ‏أَوْ ‏ ‏انْفَحِي ‏ ‏هَكَذَا وَهَكَذَا وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعِيَ ‏ ‏اللَّهُ عَلَيْكِ وَلَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِي ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[25752,25752,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏خَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُ رَجَّةَ النَّاسِ وَهُمْ يَقُولُونَ آيَةٌ وَنَحْنُ يَوْمَئِذٍ فِي فَازِعٍ فَخَرَجْتُ ‏ ‏مُتَلَفِّعَةً ‏ ‏بِقَطِيفَةٍ ‏ ‏لِلزُّبَيْرِ ‏ ‏حَتَّى دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي لِلنَّاسِ فَقُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا لِلنَّاسِ فَأَشَارَتْ بِيَدِهَا إِلَى السَّمَاءِ قَالَتْ فَصَلَّيْتُ مَعَهُمْ وَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَغَ مِنْ سَجْدَتِهِ الْأُولَى قَالَتْ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيَامًا طَوِيلًا حَتَّى رَأَيْتُ بَعْضَ مَنْ ‏ ‏يُصَلِّي ‏ ‏يَنْتَضِحُ ‏ ‏بِالْمَاءِ ثُمَّ رَكَعَ فَرَكَعَ رُكُوعًا طَوِيلًا ثُمَّ قَامَ وَلَمْ يَسْجُدْ قِيَاما طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ رُكُوعِهِ الْأَوَّلِ ثُمَّ سَجَدَ ثُمَّ سَلَّمَ وَقَدْ ‏ ‏تَجَلَّتْ ‏ ‏الشَّمْسُ ثُمَّ ‏ ‏رَقِيَ ‏ ‏الْمِنْبَرَ ثُمَّ قَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ ‏ ‏آيَاتِ ‏ ‏اللَّهِ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمْ ذَلِكَ ‏ ‏فَافْزَعُوا ‏ ‏إِلَى الصَّلَاةِ وَإِلَى ‏ ‏الصَّدَقَةِ ‏ ‏وَإِلَى ذِكْرِ اللَّهِ أَيُّهَا النَّاسُ إِنَّهُ لَمْ يَبْقَ شَيْءٌ لَمْ أَكُنْ رَأَيْتُهُ إِلَّا وَقَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا وَقَدْ أُرِيتُكُمْ ‏ ‏تُفْتَنُونَ ‏ ‏فِي قُبُورِكُمْ يُسْأَلُ أَحَدُكُمْ مَا كُنْتَ تَقُولُ وَمَا كُنْتَ تَعْبُدُ فَإِنْ قَالَ لَا أَدْرِي رَأَيْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ وَيَصْنَعُونَ شَيْئًا فَصَنَعْتُهُ قِيلَ لَهُ أَجَلْ عَلَى الشَّكِّ عِشْتَ وَعَلَيْهِ مِتَّ هَذَا ‏ ‏مَقْعَدُكَ مِنْ النَّارِ وَإِنْ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قِيلَ عَلَى ‏ ‏الْيَقِينِ ‏ ‏عِشْتَ قَالَ مِتَّ هَذَا مَقْعَدُكَ مِنْ الْجَنَّةِ وَقَدْ رَأَيْتُ خَمْسِينَ ‏ ‏أَوْ سَبْعِينَ ‏ ‏أَلْفًا يَدْخُلُونَ الْجَنَّةَ فِي مِثْلِ صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ اللَّهُمَّ اجْعَلْهُ مِنْهُمْ أَيُّهَا النَّاسُ إِنَّكُمْ لَنْ تَسْأَلُونِي عَنْ شَيْءٍ حَتَّى أَنْزِلَ إِلَّا أَخْبَرْتُكُمْ بِهِ فَقَامَ رَجُلٌ فَقَالَ مَنْ أَبِي قَالَ أَبُوكَ فُلَانٌ الَّذِي كَانَ يُنْسَبُ إِلَيْهِ ‏","","",""],[25753,25753,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏خَتَنٌ ‏ ‏كَانَ ‏ ‏لِعَطَاءٍ ‏ ‏أَخْرَجَتْ لَنَا ‏ ‏أَسْمَاءُ ‏ ‏جُبَّةً ‏ ‏مَزْرُورَةً ‏ ‏بِدِيبَاجٍ ‏ ‏قَالَتْ قَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَقِيَ الْحَرْبَ لَبِسَ هَذِهِ ‏","","",""],[25754,25754,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَيَّ ‏ ‏أُمِّي ‏ ‏وَهِيَ رَاغِبَةٌ وَهِيَ مُشْرِكَةٌ فِي عَهْدِ ‏ ‏قُرَيْشٍ ‏ ‏وَمُدَّتِهِمْ الَّتِي كَانَتْ بَيْنَهُمْ وَبَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏قَدِمَتْ عَلَيَّ وَهِيَ رَاغِبَةٌ وَهِيَ مُشْرِكَةٌ ‏ ‏أَفَأَصِلُهَا ‏ ‏قَالَ ‏ ‏صِلِيهَا ‏ ‏قَالَ وَأَظُنُّهَا ‏ ‏ظِئْرَهَا ‏","","",""],[25755,25755,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏نُؤَدِّي زَكَاةَ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدَّيْنِ ‏ ‏مِنْ قَمْحٍ ‏ ‏بِالْمُدِّ ‏ ‏الَّذِي تَقْتَاتُونَ بِهِ ‏","","",""],[25756,25756,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لِي لَمْ يَطْعَمْ ‏ ‏فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَرَشَّهُ عَلَيْهِ ‏","","",""],[25757,25757,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏أُخْتِ ‏ ‏عُكَّاشَةَ بْنِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ بِابْنٍ لِي عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَأْكُلْ الطَّعَامَ فَبَالَ فَدَعَا بِمَاءٍ فَرَشَّهُ وَدَخَلْتُ بِابْنٍ لِي قَدْ أَعْلَقْتُ عَنْهُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً عَلَيْهِ ‏ ‏مِنْ ‏ ‏الْعُذْرَةِ ‏ ‏فَقَالَ ‏ ‏عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ بِهَذَا ‏ ‏الْعِلَاقِ ‏ ‏عَلَيْكُمْ بِهَذَا الْقُسْطِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏سُفْيَانُ ‏ ‏الْعُودِ الْهِنْدِيِّ ‏ ‏فَإِنَّ بِهِ سَبْعَةَ أَشْفِيَةٍ مِنْهَا ذَاتُ الْجَنْبِ ‏ ‏يُسْعَطُ ‏ ‏مِنْ ‏ ‏الْعُذْرَةِ ‏ ‏وَيُلَدُّ مِنْ ذَاتِ الْجَنْبِ ‏","","",""],[25758,25758,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ أَبُو الْمِقْدَامِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَدِيُّ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ قَيْسٍ بِنْتَ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الثَّوْبِ يُصِيبُهُ دَمُ الْحَيْضِ قَالَ حُكِّيهِ ‏ ‏بِضِلَعٍ ‏ ‏وَاغْسِلِيهِ بِالْمَاءِ ‏ ‏وَالنَّدِّ ‏ ‏وَسِدْرٍ ‏","","",""],[25759,25759,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْحَسَنِ ‏ ‏مَوْلَى ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ ‏ ‏أَنَّها قَالَتْ ‏ ‏تُوُفِّيَ ابْنِي ‏ ‏فَجَزِعْتُ ‏ ‏عَلَيْهِ فَقُلْتُ لِلَّذِي يَغْسِلُهُ ‏ ‏لَا تَغْسِلْ ابْنِي بِالْمَاءِ الْبَارِدِ فَتَقْتُلَهُ فَانْطَلَقَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِقَوْلِهَا فَتَبَسَّمَ ثُمَّ قَالَ مَا قَالَتْ طَالَ عُمْرُهَا ‏ ‏قَالَ ‏ ‏فَلَا أَعْلَمُ امْرَأَةً عُمِّرَتْ مَا عُمِّرَتْ ‏","","",""],[25760,25760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّْ قَيْسٍ بِنْتِ مِحْصَنٍ الْأَسَدِيَّةِ ‏ ‏أُخْتِ ‏ ‏عُكَّاشَةَ ‏ ‏قَالَتْ ‏ ‏جِئْتُ بِابْنٍ لِي قَدْ أَعْلَقْتُ عَنْهُ أَخَافُ أَنْ يَكُونَ بِهِ ‏ ‏الْعُذْرَةُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ بِهَذِهِ ‏ ‏الْعَلَائِقِ ‏ ‏عَلَيْكُنَّ بِهَذَا الْعُودِ الْهِنْدِيِّ قَالَ ‏ ‏يَعْنِي ‏ ‏الْكُسْتَ ‏ ‏فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ مِنْهَا ‏ ‏ذَاتُ الْجَنْبِ ‏ ‏ثُمَّ أَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيَّهَا فَوَضَعَهُ فِي حِجْرِهِ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَنَضَحَهُ وَلَمْ يَكُنْ الصَّبِيُّ بَلَغَ أَنْ يَأْكُلَ الطَّعَامَ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَمَضَتْ السُّنَّةُ بِأَنْ يُرَشَّ بَوْلُ الصَّبِيِّ وَيُغْسَلَ بَوْلُ ‏ ‏الْجَارِيَةِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَيُسْتَسْعَطُ ‏ ‏لِلْعُذْرَةِ ‏ ‏وَيُلَدُّ ‏ ‏لِذَاتِ الْجَنْبِ ‏","","",""],[25761,25761,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ أَبِي الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ دَمِ الْحَيْضِ يُصِيبُ الثَّوْبَ فَقَالَ حُكِّيهِ وَلَوْ ‏ ‏بِضِلَعٍ ‏","","",""],[25762,25762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ دِينَارٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ قَيْسٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ دَمِ الْحَيْضِ يُصِيبُ الثَّوْبَ فَقَالَ اغْسِلِيهِ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَحُكِّيهِ ‏ ‏بِضِلَعٍ ‏","","",""],[25763,25763,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ قَيْسٍ بِنْتَ مِحْصَنٍ ‏ ‏إِحْدَى ‏ ‏بَنِي أَسَدِ بْنِ خُزَيْمَةَ ‏ ‏وَكَانَتْ مِنْ ‏ ‏الْمُهَاجِرَاتِ ‏ ‏الْأُوَلِ اللَّائِي بَايَعْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَخْبَرَتْنِي ‏ ‏أَنَّهَا أَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لَهَا لَمْ يَبْلُغْ أَنْ يَأْكُلَ الطَّعَامَ فَذَكَرَ الْحَدِيثَ وَقَالَ عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أُمِّْ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏أَنَّهَا جَاءَتْ بِابْنٍ لَهَا وَقَدْ أَعْلَقَتْ عَلَيْهِ مِنْ ‏ ‏الْعُذْرَةِ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَامَ ‏ ‏تَدْغَرْنَ ‏ ‏أَوْلَادَكُنَّ بِهَذِهِ ‏ ‏الْعُلُقِ ‏ ‏عَلَيْكُنَّ بِهَذَا الْعُودِ الْهِنْدِيِّ فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ مِنْهَا ‏ ‏ذَاتُ الْجَنْبِ ‏ ‏ثُمَّ أَخَذَ الصَّبِيَّ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ ‏ ‏فَنَضَحَهُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏مَضَتْ السُّنَّةُ بِذَلِكَ ‏","","",""],[25764,25764,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَهْلَةَ ‏ ‏امْرَأَةِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏سَالِمًا ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏يَدْخُلُ عَلَيَّ وَهُوَ ذُو لِحْيَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْضِعِيهِ فَقَالَتْ كَيْفَ أُرْضِعُهُ وَهُوَ ذُو لِحْيَةٍ فَأَرْضَعَتْهُ فَكَانَ يَدْخُلُ عَلَيْهَا ‏","","",""],[25765,25765,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ سَمِعَ ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏أُمَيْمَةَ بِنْتَ رُقَيْقَةَ ‏ ‏تَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسْوَةٍ فَلَقَّنَنَا فِيمَا اسْتَطَعْتُنَّ ‏ ‏وَأَطَقْتُنَّ ‏ ‏قُلْتُ اللَّهُ وَرَسُولُهُ أَرْحَمُ مِنَّا مِنْ أَنْفُسِنَا قُلْتُ يَا رَسُولَ اللَّهِ بَايِعْنَا قَالَ ‏ ‏إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِامْرَأَةٍ قَوْلِي لِمِائَةِ امْرَأَةٍ ‏","","",""],[25766,25766,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ التَّيْمِيَّةِ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسْوَةٍ مِنْ الْمُسْلِمِينَ لِنُبَايِعَهُ فَقُلْنَا يَا رَسُولَ اللَّهِ جِئْنَا لِنُبَايِعَكَ عَلَى أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا وَلَا نَسْرِقَ وَلَا نَزْنِيَ وَلَا نَقْتُلَ أَوْلَادَنَا وَلَا نَأْتِيَ ‏ ‏بِبُهْتَانٍ ‏ ‏نَفْتَرِيهِ ‏ ‏بَيْنَ أَيْدِينَا وَأَرْجُلِنَا وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا اسْتَطَعْتُنَّ وَأَطَعْتُنَّ قَالَتْ قُلْنَا اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنْ أَنْفُسِنَا ‏ ‏بَايِعْنَا ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏اذْهَبْنَ فَقَدْ ‏ ‏بَايَعْتُكُنَّ ‏ ‏إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ قَالَتْ وَلَمْ يُصَافِحْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنَّا امْرَأَةً ‏","","",""],[25767,25767,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ ‏ ‏أَنَّها قَالَتْ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسْوَةٍ ‏ ‏نُبَايِعُهُ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏نُبَايِعُكَ ‏ ‏عَلَى أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا وَلَا نَسْرِقَ وَلَا نَزْنِيَ وَلَا نَأْتِيَ ‏ ‏بِبُهْتَانٍ ‏ ‏نَفْتَرِيهِ ‏ ‏بَيْنَ أَيْدِينَا وَأَرْجُلِنَا وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ قَالَ قَالَ فِيمَا اسْتَطَعْتُنَّ وَأَطَعْتُنَّ قَالَتْ فَقُلْنَا اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنَّا بِأَنْفُسِنَا ‏ ‏هَلُمَّ ‏ ‏نُبَايِعُكَ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ ‏","","",""],[25768,25768,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسَاءٍ ‏ ‏نُبَايِعُهُ ‏ ‏فَأَخَذَ عَلَيْنَا مَا فِي الْقُرْآنِ أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا الْآيَةَ قَالَ فِيمَا اسْتَطَعْتُنَّ وَأَطَعْتُنَّ قُلْنَا اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنْ أَنْفُسِنَا قُلْنَا يَا رَسُولَ اللَّهِ أَلَا تُصَافِحُنَا قَالَ ‏ ‏إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ كَقَوْلِي لِمِائَةِ امْرَأَةٍ ‏","","",""],[25769,25769,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَيْمَةَ بِنْتَ رُقَيْقَةَ ‏ ‏تُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَسْتُ أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ كَقَوْلِي لِمِائَةِ امْرَأَةٍ ‏","","",""],[25770,25770,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏أُخْتِ حُذَيْفَةَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏أَمَا لَكُنَّ فِي الْفِضَّةِ مَا تَحَلَّيْنَ أَمَا إِنَّهُ لَيْسَ مِنْكُنَّ امْرَأَةٌ تَحَلَّى ذَهَبًا تُظْهِرُهُ إِلَّا عُذِّبَتْ بِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏امْرَأَتِهِ ‏ ‏عَنِ ‏ ‏أُخْتِ خُذَيْفَةَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25771,25771,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏أُخْتِ حُذَيْفَةَ ‏ ‏وَكُنَّ لَهُ أَخَوَاتٌ قَدْ أَدْرَكْنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏أَلَيْسَ لَكُنَّ فِي الْفِضَّةِ مَا تَحَلَّيْنَ أَمَا إِنَّهُ لَيْسَتْ مِنْكُنَّ امْرَأَةٌ ‏ ‏تَتَحَلَّى ذَهَبًا تُظْهِرُهُ إِلَّا عُذِّبَتْ بِهِ ‏","","",""],[25772,25772,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ النُّعْمَانِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَلْحَةَ الْأَيَامِيَّ ‏ ‏يُحَدِّثُ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏عَنِ ‏ ‏امْرَأَةٍ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الْقَيْسِ ‏ ‏عَنْ ‏ ‏أُخْتِ عَبْدِ اللَّهِ بْنِ رَوَاحَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَجَبَ الْخُرُوجُ عَلَى كُلِّ ذَاتِ نِطَاقٍ ‏","","",""],[25773,25773,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏إِلَى ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏فَسَأَلْتُهَا عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْرَجَتْ لَهُ ‏ ‏يَعْنِي إِنَاءً يَكُونُ ‏ ‏مُدًّا ‏ ‏أَوْ نَحْوَ مُدٍّ وَرُبُعٍ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَأَنَّهُ يَذْهَبُ إِلَى ‏ ‏الْهَاشِمِيِّ ‏ ‏قَالَتْ كُنْتُ ‏ ‏أُخْرِجُ لَهُ الْمَاءَ فِي هَذَا فَيَصُبُّ عَلَى يَدَيْهِ ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏مَرَّةً يَغْسِلُ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا ‏ ‏وَيَغْسِلُ وَجْهَهُ ثَلَاثًا وَيُمَضْمِضُ ثَلَاثًا وَيَسْتَنْشِقُ ثَلَاثًا وَيَغْسِلُ يَدَهُ الْيُمْنَى ثَلَاثًا وَالْيُسْرَى ثَلَاثًا وَيَمْسَحُ بِرَأْسِهِ وَقَالَ مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ ‏ ‏مُقْبِلًا وَمُدْبِرًا ثُمَّ يَغْسِلُ رِجْلَيْهِ ثَلَاثًا قَدْ جَاءَنِي ابْنُ عَمٍّ لَكَ فَسَأَلَنِي وَهُوَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَأَخْبَرْتُهُ ‏ ‏فَقَالَ ‏ ‏مَا أَجِدُ فِي كِتَابِ اللَّهِ إِلَّا مَسْحَتَيْنِ وَغَسْلَتَيْنِ ‏","","",""],[25774,25774,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏الرُّبَيِّعُ بِنْتُ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينَا فَيُكْثِرُ فَأَتَانَا فَوَضَعْنَا لَهُ ‏ ‏الْمِيضَأَةَ ‏ ‏فَتَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثًا وَمَضْمَضَ وَاسْتَنْشَقَ مَرَّةً مَرَّةً وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ رَأْسَهُ بِمَا بَقِيَ مِنْ وَضُوئِهِ فِي يَدَيْهِ مَرَّتَيْنِ بَدَأَ بِمُؤَخَّرِهِ ثُمَّ رَدَّ يَدَهُ إِلَى نَاصِيَتِهِ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا وَمَسَحَ أُذُنَيْهِ مُقَدَّمَهُمَا وَمُؤَخَّرَهُمَا ‏","","",""],[25775,25775,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ ذَكْوَانَ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَسْقِي الْقَوْمَ وَنَخْدُمُهُمْ وَنَرُدُّ الْجَرْحَى وَالْقَتْلَى إِلَى ‏ ‏الْمَدِينَةِ ‏","","",""],[25776,25776,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعْنَا لَهُ ‏ ‏الْمِيضَأَةَ ‏ ‏فَتَوَضَّأَ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ مَرَّتَيْنِ بَدَأَ بِمُؤَخَّرِهِ وَأَدْخَلَ أُصْبُعَيْهِ فِي أُذُنَيْهِ ‏","","",""],[25777,25777,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَسَنٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَأَدْخَلَ أُصْبُعَيْهِ فِي ‏ ‏حُجْرَيْ أُذُنَيْهِ ‏","","",""],[25778,25778,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقِنَاعٍ ‏ ‏فِيهِ رُطَبٌ ‏ ‏وَأَجْرُ ‏ ‏زُغْبٍ ‏ ‏فَوَضَعَ فِي يَدِي شَيْئًا فَقَالَ ‏ ‏تَحَلَّيْ بِهَذَا وَاكْتَسِي بِهَذَا ‏","","",""],[25779,25779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَمُهَنَّأُ بْنُ عَبْدِ الْحَمِيدِ أَبُو شِبْلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ ذَكْوَانَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْحُسَيْنِ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ ‏ ‏وَقَالَ ‏ ‏خَالِدٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏الرُّبَيِّعُ بِنْتُ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ عُرْسِي فَقَعَدَ فِي مَوْضِعِ فِرَاشِي هَذَا وَعِنْدِي ‏ ‏جَارِيَتَانِ ‏ ‏تَضْرِبَانِ بِالدُّفِّ ‏ ‏وَتَنْدُبَانِ ‏ ‏آبَائِي الَّذِينَ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَقَالَتَا فِيمَا تَقُولَانِ وَفِينَا نَبِيٌّ يَعْلَمُ مَا يَكُونُ فِي الْيَوْمِ وَفِي غَدٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا هَذَا فَلَا تَقُولَاهُ ‏","","",""],[25780,25780,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنِ ‏ ‏رُبَيِّعَ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَرَأَيْتُهُ مَسَحَ عَلَى رَأْسِهِ مَجَارِيَ الشَّعْرِ مَا أَقْبَلَ مِنْهُ وَمَا أَدْبَرَ وَمَسَحَ ‏ ‏صُدْغَيْهِ ‏ ‏وَأُذُنَيْهِ ظَاهِرَهُمَا وَبَاطِنَهُمَا ‏","","",""],[25781,25781,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏أَهْدَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِنَاعًا ‏ ‏مِنْ رُطَبٍ ‏ ‏وَأَجْرٍ ‏ ‏زُغْبٍ ‏ ‏قَالَتْ ‏ ‏فَأَعْطَانِي مِلْءَ كَفَّيْهِ حُلِيًّا ‏ ‏أَوْ قَالَ ذَهَبًا ‏ ‏فَقَالَ تَحَلَّيْ بِهَذَا ‏","","",""],[25782,25782,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَمَسَحَ الرَّأْسَ كُلَّهُ مِنْ فَوْقِ الشَّعْرِ كُلِّ نَاحِيَةٍ لِمُنْصَبِّ الشَّعْرِ لَا يُحَرِّكُ الشَّعْرَ عَنْ هَيْئَتِهِ ‏","","",""],[25783,25783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ ذَكْوَانَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏رُبَيِّعُ بِنْتُ مُعَوِّذٍ ‏ ‏قَالَتْ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قُرَى ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ مِنْكُمْ صَائِمًا فَلْيُتِمَّ صَوْمَهُ وَمَنْ كَانَ أَكَلَ فَلْيَصُمْ بَقِيَّةَ ‏ ‏يَوْمِهِ ‏","","",""],[25784,25784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ ذَكْوَانَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الرُّبَيِّعَ بِنْتَ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏عَنْ صَوْمِ ‏ ‏عَاشُورَاءَ ‏ ‏فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَاشُورَاءَ ‏ ‏مَنْ أَصْبَحَ مِنْكُمْ صَائِمًا قَالَ قَالُوا مِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ قَالَ فَأَتِمُّوا بَقِيَّةَ يَوْمِكُمْ وَأَرْسِلُوا إِلَى مَنْ ‏ ‏حَوْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَلْيُتِمُّوا بَقِيَّةَ يَوْمِهِمْ ‏","","",""],[25785,25785,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حُسَيْنٍ ‏ ‏قَالَ ‏ ‏كَانَ يَوْمٌ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏يَلْعَبُونَ فَدَخَلْتُ عَلَى ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏فَقَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَعَدَ عَلَى مَوْضِعَ فِرَاشِي هَذَا وَعِنْدِي ‏ ‏جَارِيَتَانِ ‏ ‏تَنْدُبَانِ ‏ ‏آبَائِي الَّذِينَ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏تَضْرِبَانِ بِالدُّفُوفِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً بِالدُّفِّ ‏ ‏فَقَالَتَا فِيمَا تَقُولَانِ وَفِينَا نَبِيٌّ يَعْلَمُ مَا يَكُونُ فِي غَدٍ فَقَالَ أَمَّا هَذَا فَلَا تَقُولَاهُ ‏","","",""],[25786,25786,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَمَسَحَ بِرَأْسِهِ الرَّأْسِ كُلِّهِ مِنْ وَرَاءِ الشَّعْرِ كُلَّ نَاحِيَةٍ لِمُنْصَبِّ الشَّعْرِ لَا يُحَرِّكُ الشَّعْرَ عَنْ هَيْئَتِهِ ‏","","",""],[25787,25787,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْخَطَّابِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ حَدَّثَتْنِي ‏ ‏سَلَامَةُ بِنْتُ مَعْقِلٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏لِلْحُبَابِ بْنِ عَمْرٍو ‏ ‏وَلِي مِنْهُ غُلَامٌ فَقَالَتْ ‏ ‏لِيَ امْرَأَتُهُ الْآنَ تُبَاعِينَ فِي دَيْنِهِ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَاحِبُ تَرِكَةِ ‏ ‏الْحُبَابِ بْنِ عَمْرٍو ‏ ‏فَقَالُوا أَخُوهُ ‏ ‏أَبُو الْيُسْرِ كَعْبُ بْنُ عَمْرٍو ‏ ‏فَدَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَبِيعُوهَا وَأَعْتِقُوهَا فَإِذَا سَمِعْتُمْ بِرَقِيقٍ قَدْ حَسَبَنِي فَأْتُونِي أُعَوِّضُكُمْ فَفَعَلُوا فَاخْتَلَفُوا فِيمَا بَيْنَهُمْ بَعْدَ وَفَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَوْمٌ أُمُّ الْوَلَدِ مَمْلُوكَةٌ لَوْلَا ذَلِكَ لَمْ يُعَوِّضْهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا وَقَالَ بَعْضُهُمْ هِيَ حُرَّةٌ قَدْ أَعْتَقَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفِيَّ كَانَ ‏ ‏الِاخْتِلَافُ ‏","","",""],[25788,25788,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏هِلَالٍ يَعْنِي ابْنَ خَبَّابٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ضُبَاعَةَ بِنْتَ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ أَنْ أَحُجَّ فَأَشْتَرِطُ قَالَ نَعَمْ قَالَتْ فَكَيْفَ أَقُولُ قَالَ قُولِي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ مَحِلِّي مِنْ الْأَرْضِ حَيْثُ تَحْبِسُنِي ‏","","",""],[25789,25789,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏ضُبَاعَةَ بِنْتِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهَا ذَبَحَتْ فِي بَيْتِهَا شَاةً فَأَرْسَلَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَطْعِمِينَا مِنْ شَاتِكُمْ فَقَالَتْ لِلرَّسُولِ وَاللَّهِ مَا بَقِيَ عِنْدَنَا إِلَّا الرَّقَبَةُ وَإِنِّي ‏ ‏أَسْتَحِي أَنْ أُرْسِلَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالرَّقَبَةِ فَرَجَعَ ‏ ‏الرَّسُولُ فَأَخْبَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ارْجِعْ إِلَيْهَا فَقُلْ لَهَا ‏ ‏أَرْسِلِي بِهَا فَإِنَّهَا هَادِيَةٌ وَأَقْرَبُ الشَّاةِ إِلَى الْخَيْرِ وَأَبْعَدُهَا مِنْ الْأَذَى ‏","","",""],[25790,25790,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَرَامٍ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِلًا فِي بَيْتِي إِذْ اسْتَيْقَظَ وَهُوَ يَضْحَكُ فَقُلْتُ بِأَبِي وَأُمِّي أَنْتَ مَا يُضْحِكُكَ فَقَالَ ‏ ‏عُرِضَ عَلَيَّ نَاسٌ مِنْ أُمَّتِي يَرْكَبُونَ ظَهْرَ هَذَا الْبَحْرِ كَالْمُلُوكِ عَلَى الْأَسِرَّةِ فَقُلْتُ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ اللَّهُمَّ اجْعَلْهَا مِنْهُمْ ثُمَّ نَامَ أَيْضًا فَاسْتَيْقَظَ وَهُوَ يَضْحَكُ فَقُلْتُ بِأَبِي وَأُمِّي مَا يُضْحِكُكَ قَالَ عُرِضَ عَلَيَّ نَاسٌ مِنْ أُمَّتِي يَرْكَبُونَ هَذَا الْبَحْرَ كَالْمُلُوكِ عَلَى الْأَسِرَّةِ فَقُلْتُ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ أَنْتِ مِنْ الْأَوَّلِينَ ‏ ‏فَغَزَتْ مَعَ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏وَكَانَ زَوْجَهَا ‏ ‏فَوَقَصَتْهَا ‏ ‏بَغْلَةٌ لَهَا ‏ ‏شَهْبَاءُ ‏ ‏فَوَقَعَتْ فَمَاتَتْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَرَامٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[25791,25791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏جُدَامَةَ بِنْتَ وَهْبٍ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ هَمَمْتُ أَنْ ‏ ‏أَنْهَى عَنْ ‏ ‏الْغِيلَةِ ‏ ‏حَتَّى ذَكَرْتُ أَنَّ ‏ ‏فَارِسَ ‏ ‏وَالرُّومَ ‏ ‏يَصْنَعُونَهُ فَلَا يَضُرُّ أَوْلَادَهُمْ ‏","","",""],[25792,25792,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏جُدَامَةَ بِنْتِ وَهْبٍ الْأَسَدِيَّةِ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَقَدْ هَمَمْتُ أَنْ ‏ ‏أَنْهَى عَنْ ‏ ‏الْغِيلَةِ ‏ ‏حَتَّى ذَكَرْتُ أَنَّ ‏ ‏فَارِسَ ‏ ‏وَالرُّومَ ‏ ‏يَفْعَلُونَ ذَلِكَ فَلَا يَضُرُّ أَوْلَادَهُمْ ‏","","",""],[25793,25793,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏جُدَامَةَ بِنْتِ وَهْبٍ الْأَسَدِيَّةِ ‏ ‏وَكَانَتْ مِنْ ‏ ‏الْمُهَاجِرَاتِ ‏ ‏الْأُوَلِ قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ هُوَ ‏ ‏الْوَأْدُ ‏ ‏الْخَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أبُو عَبدِ الْرَحَمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏فَذَكَرَهُ ‏","","",""],[25794,25794,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَبَّانُ ‏ ‏عَنْ ‏ ‏سَهْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ ‏ ‏خَرَجْتُ مِنْ الْحَمَّامِ فَلَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مِنْ أَيْنَ يَا ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏قَالَتْ مِنْ الْحَمَّامِ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا مِنْ امْرَأَةٍ تَضَعُ ثِيَابَهَا فِي غَيْرِ بَيْتِ أَحَدٍ مِنْ ‏ ‏أُمَّهَاتِهَا إِلَّا وَهِيَ هَاتِكَةٌ كُلَّ سِتْرٍ بَيْنَهَا وَبَيْنَ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زَبَّانُ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ ‏ ‏خَرَجْتُ مِنْ الْحَمَّامِ فَلَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[25795,25795,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ الدُّؤَلِيِّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏تَرْفَعُ الْحَدِيثَ قَالَتْ ‏ ‏مَنْ ‏ ‏رَابَطَ ‏ ‏فِي شَيْءٍ مِنْ سَوَاحِلِ الْمُسْلِمِينَ ثَلَاثَةَ أَيَّامٍ أَجْزَأَتْ عَنْهُ ‏ ‏رِبَاطَ ‏ ‏سَنَةٍ ‏","","",""],[25796,25796,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ وَقَالَ ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّ ‏ ‏يُحَنَّسَ أَبَا مُوسَى ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَهَا يَوْمًا فَقَالَ مِنْ أَيْنَ جِئْتِ يَا ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏فَقَالَتْ مِنْ الْحَمَّامِ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرَأَةٍ تَنْزِعُ ثِيَابَهَا إِلَّا ‏ ‏هَتَكَتْ ‏ ‏مَا بَيْنَهَا وَبَيْنَ اللَّهِ عَزَّ وَجَلَّ مِنْ سِتْرٍ ‏","","",""],[25797,25797,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏امْرَأَةِ ‏ ‏زَيْدِ بْنِ حَارِثَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَقَالَ ‏ ‏لَا يَدْخُلُ النَّارَ أَحَدٌ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏ ‏قَالَتْ ‏ ‏حَفْصَةُ ‏ ‏أَلَيْسَ اللَّهُ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا ‏} ‏قَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَهْ ‏ { ‏ثُمَّ ‏ ‏نُنَجِّي الَّذِينَ اتَّقَوْا ‏}","","",""],[25798,25798,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَرَسَ غَرْسًا أَوْ زَرَعَ زَرْعًا فَأَكَلَ مِنْهُ إِنْسَانٌ أَوْ سَبُعٌ أَوْ دَابَّةٌ أَوْ طَيْرٌ فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏","","",""],[25799,25799,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا فِي ‏ ‏حَائِطٍ ‏ ‏مِنْ ‏ ‏حَوَائِطِ ‏ ‏بَنِي النَّجَّارِ ‏ ‏فِيهِ قُبُورٌ مِنْهُمْ قَدْ مَاتُوا فِي الْجَاهِلِيَّةِ فَسَمِعَهُمْ وَهُمْ يُعَذَّبُونَ فَخَرَجَ وَهُوَ يَقُولُ ‏ ‏اسْتَعِيذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ وَإِنَّهُمْ لَيُعَذَّبُونَ فِي قُبُورِهِمْ قَالَ نَعَمْ عَذَابًا تَسْمَعُهُ الْبَهَائِمُ ‏","","",""],[25800,25800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏قَالَتْ ‏ ‏جَاءَ غُلَامُ ‏ ‏حَاطِبٍ ‏ ‏فَقَالَ وَاللَّهِ لَا يَدْخُلُ ‏ ‏حَاطِبٌ ‏ ‏الْجَنَّةَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتَ قَدْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏","","",""]];
